-- thewall.social — the whole database, in one file.
--
-- Generated by scripts/db-bundle.sh. Do not edit by hand: edit the migration it
-- came from and regenerate, or the next person to run db-deploy.sh gets a
-- different schema from the next person to paste this.
--
-- WHERE TO RUN IT
--   Supabase dashboard -> SQL Editor -> New query -> paste -> Run.
--   It takes a few seconds. There is nothing to fill in.
--
-- WHAT IT DOES
--   Creates every table, function, policy and grant, then seeds nine rooms with
--   posts in them. §5: "an empty room is worse than no room", so a project that
--   comes up bare is not finished.
--
-- SAFE TO RE-RUN? No. This is for a project with nothing in it. Against a
--   project that already has the schema it will fail on the first `create
--   table` and roll the whole thing back, which is the right outcome but not a
--   useful one — use scripts/db-deploy.sh there instead, which applies only
--   what is missing.
--
-- ONE STATEMENT MAY BE REFUSED, and it is worth knowing which. The seed inserts
--   five accounts into `auth.users` so the seeded posts have authors. On some
--   projects that schema is owned by `supabase_auth_admin` and the insert fails
--   with "permission denied for table users". The whole file rolls back if so.
--   The fix is in supabase/seed.sql's own comment: create the five accounts
--   through the Auth admin API and re-run. Everything above the seed is
--   unaffected either way.

begin;


-- ==========================================================================
-- 20260803000000_initial_schema.sql
-- ==========================================================================

-- thewall.social — initial schema
--
-- Two design claims from the decision document are enforced here rather than in
-- application code, because both are correctness properties and neither should
-- depend on every future query remembering a rule:
--
--   §3.4  post numbers are permanent and never positional
--   §3.10 commons keeps nothing

create extension if not exists citext;

-- Profiles ------------------------------------------------------------------
-- One row per account, keyed to the auth user. `name` is what appears in the
-- prompt and on every post, so it is unique and case-insensitive: `Marisol`
-- must not be able to sit next to `marisol`.
create table public.profiles (
  id         uuid primary key references auth.users (id) on delete cascade,
  name       citext not null unique,
  created_at timestamptz not null default now(),
  constraint profiles_name_shape check (name ~ '^[a-z0-9_]{2,20}$')
);

-- Rooms ---------------------------------------------------------------------
create table public.rooms (
  slug       citext primary key,
  gloss      text not null,
  -- §3.10 — an ephemeral room is a hallway: posts expire, no permanent ids,
  -- no threads. Commons is the only one at launch.
  ephemeral  boolean not null default false,
  sort_order integer not null default 0,
  -- §3.4 — the allocator. Monotonic, never decremented, never reused, so a
  -- deleted post does not renumber anything after it.
  next_post_no integer not null default 1,
  created_at timestamptz not null default now(),
  constraint rooms_slug_shape check (slug ~ '^[a-z0-9-]{2,24}$')
);

-- Posts ---------------------------------------------------------------------
-- `id` is the internal surrogate. `post_no` is the address the user sees and
-- types (`go 12`) and the one that appears in the URL (`/music/12`) — the same
-- value in both places, which is what makes shareable URLs free (§3.4).
create table public.posts (
  id         bigint generated always as identity primary key,
  room_slug  citext not null references public.rooms (slug) on delete cascade,
  post_no    integer not null,
  author_id  uuid not null references public.profiles (id) on delete cascade,
  body       text not null,
  created_at timestamptz not null default now(),
  constraint posts_body_length check (char_length(body) between 1 and 2000),
  -- The address is unique within its room, and that is enforced by the
  -- database rather than trusted from the client.
  constraint posts_address unique (room_slug, post_no)
);

create index posts_room_recent on public.posts (room_slug, created_at desc);

-- Replies -------------------------------------------------------------------
-- §4.3 — replies are flat, permanently. There is deliberately no parent_id:
-- the constraint is stated in the schema so that "add threading later" cannot
-- happen by accident.
create table public.replies (
  id         bigint generated always as identity primary key,
  post_id    bigint not null references public.posts (id) on delete cascade,
  author_id  uuid not null references public.profiles (id) on delete cascade,
  body       text not null,
  created_at timestamptz not null default now(),
  constraint replies_body_length check (char_length(body) between 1 and 2000)
);

create index replies_post_order on public.replies (post_id, created_at);

-- Ephemerality --------------------------------------------------------------

-- The single definition of "still here". Everything else refers to this, so
-- the 24-hour window is stated once (§3.10).
create or replace function public.is_visible (p_room citext, p_created_at timestamptz)
returns boolean
language sql
stable
as $$
  select not coalesce((select ephemeral from public.rooms where slug = p_room), false)
      or p_created_at > now() - interval '24 hours';
$$;

-- §3.10 — commons has no threads. Enforced at write time, since a reply to an
-- expiring post is a thread by another name.
create or replace function public.reject_reply_in_ephemeral_room ()
returns trigger
language plpgsql
as $$
declare
  v_ephemeral boolean;
begin
  select r.ephemeral into v_ephemeral
    from public.posts p
    join public.rooms r on r.slug = p.room_slug
   where p.id = new.post_id;

  if v_ephemeral then
    raise exception 'commons does not keep threads'
      using errcode = 'check_violation';
  end if;

  return new;
end;
$$;

create trigger replies_reject_ephemeral
  before insert on public.replies
  for each row execute function public.reject_reply_in_ephemeral_room ();

-- Post allocation -----------------------------------------------------------

-- §3.4 — the client never picks a number. The counter is bumped and the row is
-- inserted in one statement inside one transaction, so two people posting at
-- the same instant cannot land on the same address, and nothing is ever reused.
create or replace function public.create_post (p_room citext, p_body text)
returns public.posts
language plpgsql
security definer
set search_path = public
as $$
declare
  v_post_no integer;
  v_post    public.posts;
begin
  if auth.uid () is null then
    raise exception 'you have to be signed in to say something'
      using errcode = 'insufficient_privilege';
  end if;

  -- The UPDATE takes a row lock on the room, which serialises concurrent
  -- allocation without a separate sequence per room.
  update public.rooms
     set next_post_no = next_post_no + 1
   where slug = p_room
  returning next_post_no - 1 into v_post_no;

  if v_post_no is null then
    raise exception 'no room called %', p_room using errcode = 'no_data_found';
  end if;

  insert into public.posts (room_slug, post_no, author_id, body)
  values (p_room, v_post_no, auth.uid (), p_body)
  returning * into v_post;

  return v_post;
end;
$$;

revoke all on function public.create_post (citext, text) from public;
grant execute on function public.create_post (citext, text) to authenticated;

-- Row level security --------------------------------------------------------
-- §3.9 — reading is anonymous. Every select policy is open; only writing needs
-- an account, and the first `say` is what asks for one.

alter table public.profiles enable row level security;
alter table public.rooms    enable row level security;
alter table public.posts    enable row level security;
alter table public.replies  enable row level security;

create policy "anyone may read profiles"
  on public.profiles for select using (true);

create policy "you may create your own profile"
  on public.profiles for insert with check (id = auth.uid ());

create policy "you may edit your own profile"
  on public.profiles for update using (id = auth.uid ()) with check (id = auth.uid ());

create policy "anyone may read rooms"
  on public.rooms for select using (true);

-- §3.10 — the expiry is a read policy, not a filter every query has to
-- remember. Commons is structurally incapable of keeping anything.
create policy "anyone may read posts that are still here"
  on public.posts for select using (public.is_visible (room_slug, created_at));

-- Posting goes through create_post, which owns the numbering. Direct inserts
-- would have to pick a post_no, so they are simply not allowed.
create policy "you may edit your own posts"
  on public.posts for update using (author_id = auth.uid ()) with check (author_id = auth.uid ());

create policy "anyone may read replies to posts that are still here"
  on public.replies for select using (
    exists (
      select 1 from public.posts p
       where p.id = replies.post_id
         and public.is_visible (p.room_slug, p.created_at)
    )
  );

create policy "you may reply as yourself"
  on public.replies for insert with check (author_id = auth.uid ());

-- The lobby ------------------------------------------------------------------
-- §3.11 — `look` at the lobby shows each room with its most recent activity:
-- last post, how long ago, who said it. It costs nothing and it is the
-- difference between a busy building and a list of doors.
--
-- security_invoker makes the view run with the caller's rights, so the reader's
-- RLS applies to the rows underneath it. Without it a view silently becomes a
-- hole in the policies it sits on top of.
create view public.room_overview
with (security_invoker = true) as
select
  r.slug,
  r.gloss,
  r.ephemeral,
  r.sort_order,
  latest.body       as latest_body,
  latest.created_at as latest_at,
  author.name       as latest_author
from public.rooms r
left join lateral (
  select p.body, p.created_at, p.author_id
    from public.posts p
   where p.room_slug = r.slug
     -- Stated again rather than left to RLS alone: a service-role reader
     -- bypasses policies, and commons must look empty to everyone (§3.10).
     and public.is_visible (p.room_slug, p.created_at)
   order by p.created_at desc
   limit 1
) latest on true
left join public.profiles author on author.id = latest.author_id;

-- Grants --------------------------------------------------------------------
-- Stated explicitly rather than leaning on the hosted project's default
-- privileges, so the migration means the same thing wherever it is applied.
-- RLS decides which rows; these decide which verbs.

grant select on public.rooms, public.posts, public.replies, public.profiles,
  public.room_overview to anon, authenticated;

-- No direct insert on posts: numbering belongs to create_post (§3.4), and a
-- client that could insert would have to choose a post_no itself.
grant insert on public.replies, public.profiles to authenticated;
grant update on public.posts, public.profiles to authenticated;

-- Realtime ------------------------------------------------------------------
alter publication supabase_realtime add table public.posts;
alter publication supabase_realtime add table public.replies;

;


-- ==========================================================================
-- 20260803010000_signup_rate_limit.sql
-- ==========================================================================

-- §4.7 — unverified posting at launch, with a rate limit on new accounts.
--
-- The flow posts immediately and sends the key in parallel, which means
-- throwaway addresses get in. For a small community that is fine and the manual
-- kill switch covers it; what it cannot absorb is someone minting accounts in a
-- loop. This is the cheap bound that buys time, and the thing to revisit the
-- moment volume makes the kill switch impractical.

create table public.signup_attempts (
  id         bigint generated always as identity primary key,
  -- Hashed rather than stored: the bound needs to distinguish callers, not
  -- identify them, and an unhashed address is a liability with no upside.
  client_hash text not null,
  created_at timestamptz not null default now()
);

create index signup_attempts_recent on public.signup_attempts (client_hash, created_at desc);

-- Only the server, holding the service-role key, ever touches this table.
alter table public.signup_attempts enable row level security;
revoke all on public.signup_attempts from anon, authenticated;

-- Records the attempt and reports whether it is over the line, in one call, so
-- there is no gap between the check and the write for a burst to slip through.
create or replace function public.record_signup_attempt (
  p_client_hash text,
  p_limit integer default 5,
  p_window interval default interval '1 hour'
)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
  v_recent integer;
begin
  insert into public.signup_attempts (client_hash) values (p_client_hash);

  select count(*) into v_recent
    from public.signup_attempts
   where client_hash = p_client_hash
     and created_at > now() - p_window;

  return v_recent <= p_limit;
end;
$$;

revoke all on function public.record_signup_attempt (text, integer, interval) from public, anon, authenticated;

-- Keeps the table from growing without bound. Run from a scheduled job, or by
-- hand — there is no cron in scope at launch (§6).
create or replace function public.prune_signup_attempts ()
returns void
language sql
security definer
set search_path = public
as $$
  delete from public.signup_attempts where created_at < now() - interval '7 days';
$$;

revoke all on function public.prune_signup_attempts () from public, anon, authenticated;

;


-- ==========================================================================
-- 20260803020000_verify_to_continue.sql
-- ==========================================================================

-- §4.7, revised.
--
-- The document weighed unverified posting purely as a moderation question:
-- throwaway addresses, the manual kill switch, abuse at scale. It never asked
-- whether someone can come back *as themselves*, and that turns out to be the
-- sharper problem. An unverified address may be a typo or invented, so a magic
-- link sent to it is not a recovery path — on a second device the only reliable
-- move is to sign up again. Since names are uniquely reserved forever (§4.6),
-- every abandoned account permanently burns a handle in a community where the
-- handle *is* the identity. Identity that does not survive the trip also makes
-- §4.1's notifications pointless before they are even built.
--
-- The resolution keeps §3.9 whole: the held sentence still posts the instant
-- the account exists, because that moment is the best thing in the design.
-- Everything after it asks you to click the link first. The friction lands
-- after the payoff rather than in front of it, which is also what makes the
-- link necessary rather than decorative.

-- Our own signal, deliberately not auth.users.email_confirmed_at.
--
-- Signup mints a session immediately, and the only way to do that confirms the
-- address as a side effect — so GoTrue's flag says "confirmed" for an address
-- nobody has ever proven they can read. This column means something narrower
-- and true: they clicked a link that arrived in that inbox.
alter table public.profiles
  add column verified_at timestamptz;

comment on column public.profiles.verified_at is
  'When they followed a link sent to their address. Null means unverified: one contribution, then they are asked.';

-- One contribution before verifying — that is the §3.9 held message and
-- nothing more.
create or replace function public.may_contribute (p_user uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select
    coalesce((select verified_at is not null from public.profiles where id = p_user), false)
    or (
      (select count(*) from public.posts where author_id = p_user)
      + (select count(*) from public.replies where author_id = p_user)
    ) = 0;
$$;

grant execute on function public.may_contribute (uuid) to authenticated;

-- Enforced here rather than in the client for the same reason the other two
-- invariants are: a rule that lives in application code is a rule every future
-- caller has to remember.
create or replace function public.create_post (p_room citext, p_body text)
returns public.posts
language plpgsql
security definer
set search_path = public
as $$
declare
  v_post_no integer;
  v_post    public.posts;
begin
  if auth.uid () is null then
    raise exception 'you have to be signed in to say something'
      using errcode = 'insufficient_privilege';
  end if;

  if not public.may_contribute (auth.uid ()) then
    raise exception 'check your email to keep saying things'
      using errcode = 'insufficient_privilege';
  end if;

  update public.rooms
     set next_post_no = next_post_no + 1
   where slug = p_room
  returning next_post_no - 1 into v_post_no;

  if v_post_no is null then
    raise exception 'no room called %', p_room using errcode = 'no_data_found';
  end if;

  insert into public.posts (room_slug, post_no, author_id, body)
  values (p_room, v_post_no, auth.uid (), p_body)
  returning * into v_post;

  return v_post;
end;
$$;

revoke all on function public.create_post (citext, text) from public;
grant execute on function public.create_post (citext, text) to authenticated;

-- Replies are inserted directly, so they need their own gate. This runs before
-- the ephemeral-room check, which is the right order: "verify first" is the
-- more useful thing to hear.
create or replace function public.require_contribution_allowed ()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if not public.may_contribute (new.author_id) then
    raise exception 'check your email to keep saying things'
      using errcode = 'insufficient_privilege';
  end if;
  return new;
end;
$$;

create trigger replies_require_verified
  before insert on public.replies
  for each row execute function public.require_contribution_allowed ();

-- The seeded accounts predate any of this and are not people with inboxes, so
-- mark them verified rather than leaving them one post from being locked.
update public.profiles set verified_at = now() where verified_at is null;

;


-- ==========================================================================
-- 20260804000000_column_scoped_grants.sql
-- ==========================================================================

-- Closing two holes that defeat controls this schema claims to enforce.
--
-- Root cause, both times: `grant update on <table> to authenticated` is
-- table-wide, while the policy only checks *row* ownership. A user may
-- therefore change any column of their own row. The policies were written as
-- if they constrained what could change; they only constrain whose row it is.
--
-- What that allowed, from the browser console with the anon key that is
-- already in the bundle:
--
--   update profiles set verified_at = now() where id = <me>
--     → may_contribute() true forever. The whole §4.7 gate, which the previous
--       migration exists to add, bypassed without touching email.
--
--   update posts set created_at = now() + interval '1 year' where id = <mine>
--     → is_visible() never expires it. §3.10's "commons is structurally
--       incapable of keeping anything" was simply false, and with no DELETE
--       policy nobody could remove the result through the app.
--
-- The same grant also allowed silent retroactive edits of a post's body, moving
-- a post between rooms, and squatting an unallocated post_no — which later
-- makes create_post fail on the unique constraint for everybody.

-- Nothing in the product edits a post or a name. There is no `edit` verb and
-- no `rename` verb in the command registry, so these grants bought nothing and
-- cost everything. §4.6's one-free-rename will add back exactly one column,
-- through a function that can enforce "once".
revoke update on public.posts from authenticated;
revoke update on public.profiles from authenticated;

drop policy if exists "you may edit your own posts" on public.posts;
drop policy if exists "you may edit your own profile" on public.profiles;

-- Verification is now the database's to record, not the client's to assert.
--
-- /auth/callback used to write verified_at through the user's own session,
-- which is precisely why the grant had to exist. Moving it here lets the grant
-- go: security definer runs as the owner, and auth.uid() means a caller can
-- only ever mark themselves.
create or replace function public.mark_verified ()
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.uid () is null then
    raise exception 'not signed in' using errcode = 'insufficient_privilege';
  end if;

  update public.profiles
     set verified_at = now()
   where id = auth.uid ()
     and verified_at is null;
end;
$$;

revoke all on function public.mark_verified () from public, anon;
grant execute on function public.mark_verified () to authenticated;

-- Bodies -------------------------------------------------------------------
-- Length-only validation let two dumb things through: a whitespace-only post,
-- which permanently consumes an address and renders as a blank entry, and a
-- post of two thousand newlines, which is the closest thing this design has to
-- a griefing primitive — it floods a scrollback and needs no automation.

alter table public.posts
  add constraint posts_body_not_blank check (char_length(btrim(body)) > 0),
  add constraint posts_body_line_limit
    check (char_length(body) - char_length(replace(body, E'\n', '')) <= 20);

alter table public.replies
  add constraint replies_body_not_blank check (char_length(btrim(body)) > 0),
  add constraint replies_body_line_limit
    check (char_length(body) - char_length(replace(body, E'\n', '')) <= 20);

-- Rate limiting, generalised --------------------------------------------------
-- §4.7 bounded new accounts and nothing else. /api/verify/resend then arrived
-- with no bound at all: every call mints a link and sends real mail, so a loop
-- burns the mail provider's quota in a minute and can be pointed at a stranger's
-- address, because signup never proves ownership. Supabase's own email throttle
-- does not apply, since generateLink mints without sending.

alter table public.signup_attempts
  add column kind text not null default 'signup';

drop index if exists signup_attempts_recent;
create index signup_attempts_recent
  on public.signup_attempts (kind, client_hash, created_at desc);

create or replace function public.record_attempt (
  p_kind        text,
  p_client_hash text,
  p_limit       integer default 5,
  p_window      interval default interval '1 hour'
)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
  v_recent integer;
begin
  -- Recorded and counted in one call, so a burst cannot slip between the
  -- check and the write.
  insert into public.signup_attempts (kind, client_hash) values (p_kind, p_client_hash);

  select count(*) into v_recent
    from public.signup_attempts
   where kind = p_kind
     and client_hash = p_client_hash
     and created_at > now() - p_window;

  return v_recent <= p_limit;
end;
$$;

revoke all on function public.record_attempt (text, text, integer, interval)
  from public, anon, authenticated;

-- Kept so the signup route needs no change, and so the name still says what it
-- is for at the call site.
create or replace function public.record_signup_attempt (
  p_client_hash text,
  p_limit integer default 5,
  p_window interval default interval '1 hour'
)
returns boolean
language sql
security definer
set search_path = public
as $$
  select public.record_attempt ('signup', p_client_hash, p_limit, p_window);
$$;

revoke all on function public.record_signup_attempt (text, integer, interval)
  from public, anon, authenticated;

;


-- ==========================================================================
-- 20260804010000_mail.sql
-- ==========================================================================

-- §4.1 — notifications. The document's own highest-priority unsolved item:
--
--   "Nothing currently tells you someone replied. No notification means no
--    reason to return, which makes this the difference between a place people
--    try and a place people check."
--
-- Its lean is specific, so this is implementation rather than design:
--
--   "status bar shows the count persistently; `mail` lists them with `go <id>`
--    to jump. Pull-only, no push, no email. That's on-brand and it's less to
--    build."
--
-- One column and two functions. Unread means: replies to posts I wrote, newer
-- than the last time I looked, that I did not write myself.

alter table public.profiles
  add column mail_seen_at timestamptz not null default now();

comment on column public.profiles.mail_seen_at is
  'Last time they read their mail. Everything newer than this is unread (§4.1).';

-- The reply side of the join is by author; without this every count is a scan.
create index replies_author_recent on public.replies (author_id, created_at desc);
create index posts_author on public.posts (author_id);

-- security definer because the whole point is a count about *you*, derived
-- from rows belonging to other people. auth.uid() means it can only ever be
-- about the caller.
create or replace function public.mail_count ()
returns integer
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(count(*), 0)::integer
    from public.replies r
    join public.posts p on p.id = r.post_id
   where p.author_id = auth.uid ()
     and r.author_id <> auth.uid ()
     and r.created_at > (select mail_seen_at from public.profiles where id = auth.uid ());
$$;

-- Returns the address alongside the words, because §4.1's lean is that mail
-- lists them "with `go <id>` to jump" — a notification you cannot walk to is
-- just an alert.
create or replace function public.mail ()
returns table (
  room       citext,
  post_no    integer,
  author     citext,
  body       text,
  created_at timestamptz
)
language sql
stable
security definer
set search_path = public
as $$
  select p.room_slug, p.post_no, author.name, r.body, r.created_at
    from public.replies r
    join public.posts p on p.id = r.post_id
    join public.profiles author on author.id = r.author_id
   where p.author_id = auth.uid ()
     and r.author_id <> auth.uid ()
     and r.created_at > (select mail_seen_at from public.profiles where id = auth.uid ())
   order by r.created_at desc
   limit 50;
$$;

create or replace function public.mark_mail_seen ()
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.uid () is null then
    raise exception 'not signed in' using errcode = 'insufficient_privilege';
  end if;

  update public.profiles set mail_seen_at = now() where id = auth.uid ();
end;
$$;

revoke all on function public.mail_count () from public, anon;
revoke all on function public.mail () from public, anon;
revoke all on function public.mark_mail_seen () from public, anon;

grant execute on function public.mail_count () to authenticated;
grant execute on function public.mail () to authenticated;
grant execute on function public.mark_mail_seen () to authenticated;

;


-- ==========================================================================
-- 20260804020000_moderation.sql
-- ==========================================================================

-- The operator's day one.
--
-- §6 puts "any moderation tooling beyond a manual kill switch" out of scope,
-- which means the manual kill switch itself is in — and it did not exist. There
-- was no DELETE policy on any table, no ban, and no way to hide a post or a
-- room. The only lever was hand-written SQL, and the obvious hand-written SQL
-- was the wrong one: deleting an account cascades away every reply *other
-- people* wrote underneath it, and frees the offender's handle for immediate
-- re-registration, in a design where the handle is the identity (§4.6).
--
-- So everything here is a soft delete. Nothing is destroyed, the address is
-- never released (§3.4's allocator is monotonic, so hiding post 12 renumbers
-- nothing and 12 is never handed out again), and every lever has its inverse.
--
-- Also here, because they are the same day: a rate limit on contributing, which
-- did not exist at all, and §4.2's decay rule — "written but not enabled".

-- Columns ---------------------------------------------------------------------

alter table public.profiles
  add column banned_at     timestamptz,
  add column banned_reason text;

comment on column public.profiles.banned_at is
  'Set by ban(). The row stays: the name remains reserved and dead (§4.6), and their replies stay under other people''s posts.';

alter table public.posts   add column hidden_at timestamptz;
alter table public.replies add column hidden_at timestamptz;

comment on column public.posts.hidden_at is
  'Soft delete. The row and its replies survive, the address is never reused, and unhide_post() puts it back exactly as it was.';

alter table public.rooms
  add column hidden_at   timestamptz,
  add column archived_at timestamptz;

comment on column public.rooms.hidden_at is
  'The kill switch: the room and everything in it stop existing for readers.';

comment on column public.rooms.archived_at is
  '§4.2 decay — quiet, not gone. Dropped from the lobby listing, still reachable by name, and cleared the moment somebody posts.';

-- The rate limit and may_contribute both ask "what has this person written
-- lately", which was a scan of every post they had ever made.
drop index if exists posts_author;
create index posts_author_recent on public.posts (author_id, created_at desc);

-- Visibility ------------------------------------------------------------------
--
-- Both helpers are security definer on purpose. A policy expression runs with
-- the caller's rights, so a policy on `posts` that looked up `rooms` directly
-- would be filtered by the rooms policy — and once hidden rooms are unreadable,
-- that lookup returns no row and the check silently inverts. Reading the rule
-- has to bypass the rule.

create or replace function public.room_is_open (p_room citext)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select coalesce((select hidden_at is null from public.rooms where slug = p_room), false);
$$;

create or replace function public.post_is_readable (p_post_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select coalesce((
    select p.hidden_at is null
       and public.is_visible (p.room_slug, p.created_at)
       and public.room_is_open (p.room_slug)
      from public.posts p
     where p.id = p_post_id
  ), false);
$$;

grant execute on function public.room_is_open (citext) to anon, authenticated;
grant execute on function public.post_is_readable (bigint) to anon, authenticated;

-- A hidden room is gone. An archived one is merely quiet, so it stays readable
-- by name — §4.2's decay is "hidden from `look` and archived", not deleted.
drop policy "anyone may read rooms" on public.rooms;
create policy "anyone may read rooms"
  on public.rooms for select using (hidden_at is null);

drop policy "anyone may read posts that are still here" on public.posts;
create policy "anyone may read posts that are still here"
  on public.posts for select using (
    hidden_at is null
    and public.is_visible (room_slug, created_at)
    and public.room_is_open (room_slug)
  );

drop policy "anyone may read replies to posts that are still here" on public.replies;
create policy "anyone may read replies to posts that are still here"
  on public.replies for select using (
    hidden_at is null and public.post_is_readable (post_id)
  );

-- The read rule and the write rule are the same rule. Without this, a hidden
-- post is unreadable but still repliable by anyone who kept its internal id —
-- the client cannot find it, which is not the same as it being refused.
drop policy "you may reply as yourself" on public.replies;
create policy "you may reply as yourself"
  on public.replies for insert
  with check (author_id = auth.uid () and public.post_is_readable (post_id));

-- The lobby -------------------------------------------------------------------
-- Archived and hidden rooms leave the listing; a hidden post stops being a
-- room's proof of life. Stated here as well as in the policies because a
-- service-role reader bypasses RLS, and this view is what the lobby is.
create or replace view public.room_overview
with (security_invoker = true) as
select
  r.slug,
  r.gloss,
  r.ephemeral,
  r.sort_order,
  latest.body       as latest_body,
  latest.created_at as latest_at,
  author.name       as latest_author
from public.rooms r
left join lateral (
  select p.body, p.created_at, p.author_id
    from public.posts p
   where p.room_slug = r.slug
     and p.hidden_at is null
     and public.is_visible (p.room_slug, p.created_at)
   order by p.created_at desc
   limit 1
) latest on true
left join public.profiles author on author.id = latest.author_id
where r.hidden_at is null
  and r.archived_at is null;

-- Who may contribute ----------------------------------------------------------
--
-- Two changes beyond the ban.
--
-- VOLATILE, not STABLE. A stable function sees the snapshot taken at the start
-- of the *statement*, so `select create_post(...) from generate_series(1, 25)`
-- had every call observe "this account has written nothing" and the §4.7 gate
-- passed twenty-five times. Unreachable through PostgREST, where one RPC is one
-- statement, but it is the gate being enforced by the shape of the client
-- rather than by the database — which is the thing this file exists to stop
-- being true. A rate limit built on a stable read would have the same hole, and
-- there the loophole is the entire attack.
--
-- `exists` rather than `count(*)`: the question was only ever "any at all", and
-- the count read every row to answer it.
create or replace function public.may_contribute (p_user uuid)
returns boolean
language sql
volatile
security definer
set search_path = public
as $$
  select coalesce((
    select case
             when p.banned_at   is not null then false
             when p.verified_at is not null then true
             else not exists (select 1 from public.posts   where author_id = p_user)
              and not exists (select 1 from public.replies where author_id = p_user)
           end
      from public.profiles p
     where p.id = p_user
  ), false);
$$;

grant execute on function public.may_contribute (uuid) to authenticated;

-- One gate for both write paths.
--
-- There was no rate limit on posting or replying at all. Twenty contributions
-- in five minutes is far above a fast conversation in a hallway (§3.10) and far
-- below anything a script would bother with, and it counts posts and replies
-- together because they are one verb (§3.3) and limiting them separately just
-- doubles the allowance.
--
-- Hidden rows still count. Hiding what somebody flooded should not hand them a
-- fresh allowance to do it again.
create or replace function public.require_can_contribute (p_user uuid)
returns void
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_banned timestamptz;
  v_reason text;
  v_recent integer;
begin
  select banned_at, banned_reason into v_banned, v_reason
    from public.profiles where id = p_user;

  if v_banned is not null then
    -- §3.7 — say what is wrong. There is no fix to name here, so the reason is
    -- the most useful thing it can carry.
    raise exception 'you can''t say things here anymore%',
      case when coalesce(v_reason, '') = '' then '.' else ': ' || v_reason end
      using errcode = 'insufficient_privilege';
  end if;

  if not public.may_contribute (p_user) then
    raise exception 'check your email to keep saying things'
      using errcode = 'insufficient_privilege';
  end if;

  select count(*) into v_recent
    from (
      select created_at from public.posts
       where author_id = p_user and created_at > now() - interval '5 minutes'
      union all
      select created_at from public.replies
       where author_id = p_user and created_at > now() - interval '5 minutes'
    ) recent;

  if v_recent >= 20 then
    raise exception 'too fast — that is a lot of words in a very short time'
      using errcode = 'check_violation';
  end if;
end;
$$;

revoke all on function public.require_can_contribute (uuid) from public, anon;

create or replace function public.create_post (p_room citext, p_body text)
returns public.posts
language plpgsql
security definer
set search_path = public
as $$
declare
  v_post_no integer;
  v_post    public.posts;
begin
  if auth.uid () is null then
    raise exception 'you have to be signed in to say something'
      using errcode = 'insufficient_privilege';
  end if;

  perform public.require_can_contribute (auth.uid ());

  -- `hidden_at is null` is what makes the kill switch hold here: this function
  -- is security definer, so the read policy that hides the room does not apply,
  -- and anyone who remembered the name could keep posting into it.
  --
  -- Clearing archived_at in the same statement is §4.2's decay rule undoing
  -- itself: a room comes back to the lobby the moment somebody says something
  -- in it, at no extra cost.
  update public.rooms
     set next_post_no = next_post_no + 1,
         archived_at  = null
   where slug = p_room
     and hidden_at is null
  returning next_post_no - 1 into v_post_no;

  if v_post_no is null then
    raise exception 'no room called %', p_room using errcode = 'no_data_found';
  end if;

  insert into public.posts (room_slug, post_no, author_id, body)
  values (p_room, v_post_no, auth.uid (), p_body)
  returning * into v_post;

  return v_post;
end;
$$;

revoke all on function public.create_post (citext, text) from public;
grant execute on function public.create_post (citext, text) to authenticated;

create or replace function public.require_contribution_allowed ()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  perform public.require_can_contribute (new.author_id);
  return new;
end;
$$;

-- The levers -------------------------------------------------------------------
--
-- service_role only. There is deliberately no admin flag on profiles and no
-- in-app moderation surface: §6 asks for a *manual* kill switch, and an admin
-- bit that authenticated users can be checked against is a privilege escalation
-- target that buys nothing when the operator is one person with psql
-- (scripts/moderate.sh).

create or replace function public.hide_post (p_room citext, p_post_no integer, p_hide boolean default true)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_count integer;
begin
  update public.posts
     set hidden_at = case when p_hide then now() else null end
   where room_slug = p_room
     and post_no = p_post_no
     and (hidden_at is null) = p_hide;
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;

create or replace function public.hide_reply (p_reply_id bigint, p_hide boolean default true)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_count integer;
begin
  update public.replies
     set hidden_at = case when p_hide then now() else null end
   where id = p_reply_id
     and (hidden_at is null) = p_hide;
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;

create or replace function public.hide_room (p_slug citext, p_hide boolean default true)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_count integer;
begin
  update public.rooms
     set hidden_at = case when p_hide then now() else null end
   where slug = p_slug
     and (hidden_at is null) = p_hide;
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;

-- Ban, and the one composite operation the operator actually needs at 2am.
--
-- The account is not deleted, and that is the point: deleting it cascades away
-- every reply other people wrote under their posts, and releases the handle for
-- re-registration. Banned means the name stays reserved and dead (§4.6).
--
-- Hiding what they said is a separate argument rather than automatic, because
-- banning somebody for one thing should not silently erase a year of ordinary
-- conversation other people were part of.
create or replace function public.ban (
  p_name       citext,
  p_reason     text default null,
  p_hide_posts boolean default true
)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_id     uuid;
  v_hidden integer := 0;
begin
  select id into v_id from public.profiles where name = p_name;
  if v_id is null then
    raise exception 'no one called %', p_name using errcode = 'no_data_found';
  end if;

  update public.profiles
     set banned_at = now(), banned_reason = p_reason
   where id = v_id;

  if p_hide_posts then
    update public.posts set hidden_at = now()
     where author_id = v_id and hidden_at is null;
    get diagnostics v_hidden = row_count;

    update public.replies set hidden_at = now()
     where author_id = v_id and hidden_at is null;
  end if;

  return v_hidden;
end;
$$;

-- Undo, including the hiding — an operator who cannot reverse a mistake has a
-- lever they will hesitate to pull, which is the same as not having one.
create or replace function public.unban (p_name citext, p_restore_posts boolean default true)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_id       uuid;
  v_restored integer := 0;
begin
  select id into v_id from public.profiles where name = p_name;
  if v_id is null then
    raise exception 'no one called %', p_name using errcode = 'no_data_found';
  end if;

  update public.profiles
     set banned_at = null, banned_reason = null
   where id = v_id;

  if p_restore_posts then
    update public.posts set hidden_at = null
     where author_id = v_id and hidden_at is not null;
    get diagnostics v_restored = row_count;

    update public.replies set hidden_at = null
     where author_id = v_id and hidden_at is not null;
  end if;

  return v_restored;
end;
$$;

-- §4.2 — "decay rules written but not enabled."
--
-- Written, and deliberately called by nothing: no cron, no trigger, no schedule.
-- Enabling it is one line in a scheduler on the day the room list stops looking
-- alive on its own, which is the condition §4.2 sets for revisiting this.
--
-- Ephemeral rooms are skipped: commons is empty by design every morning (§3.10)
-- and archiving the front door is not decay, it is a bug.
create or replace function public.archive_quiet_rooms (p_idle interval default interval '7 days')
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_count integer;
begin
  update public.rooms r
     set archived_at = now()
   where r.archived_at is null
     and r.hidden_at is null
     and not r.ephemeral
     and not exists (
       select 1 from public.posts p
        where p.room_slug = r.slug
          and p.hidden_at is null
          and p.created_at > now() - p_idle
     );
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;

do $$
declare
  fn text;
begin
  foreach fn in array array[
    'public.hide_post (citext, integer, boolean)',
    'public.hide_reply (bigint, boolean)',
    'public.hide_room (citext, boolean)',
    'public.ban (citext, text, boolean)',
    'public.unban (citext, boolean)',
    'public.archive_quiet_rooms (interval)'
  ]
  loop
    execute format('revoke all on function %s from public, anon, authenticated', fn);
    -- service_role exists on every Supabase project; the test shim creates it.
    if exists (select 1 from pg_roles where rolname = 'service_role') then
      execute format('grant execute on function %s to service_role', fn);
    end if;
  end loop;
end
$$;

;


-- ==========================================================================
-- 20260804030000_rename.sql
-- ==========================================================================

-- §4.6, revised — rename as often as you like.
--
-- The document leaned "one free rename, ever. Old name stays reserved and dead
-- so nobody can impersonate." Both halves are now decided differently, and the
-- second half is the one that costs something, so it is worth being precise
-- about what was traded.
--
-- Unlimited, because the failure case §4.6 names — "someone who picks badly at
-- 2am is stuck with it, and that's a real reason to leave" — is not a
-- once-per-lifetime event. A cap just moves the trap one step further along.
--
-- Released immediately, because a name nobody is using is a name nobody is
-- using. The cost is real: `posts` join `profiles.name` live, so a rename
-- rewrites attribution on everything you ever said, and the name you leave can
-- be taken by somebody else that minute. Somebody could build trust as
-- `marisol`, rename, and let a stranger inherit every conversation that says
-- "as marisol said".
--
-- So the mitigation is disclosure rather than a lock: a name that changed hands
-- recently says so on the profile of whoever holds it now. That warns the
-- reader, which is where impersonation actually lands, without publishing
-- anybody's old handles — which would defeat the entire point of letting
-- someone walk away from a name they regret.

alter table public.profiles
  add column name_since timestamptz not null default now();

comment on column public.profiles.name_since is
  'When the current name was taken. Feeds the "this name changed hands recently" notice on a profile.';

-- Not readable by anyone. It exists to answer one question — "was this name
-- somebody else's lately?" — and that question is answered by a function that
-- returns a timestamp and never says whose it was.
create table public.name_history (
  id          bigint generated always as identity primary key,
  profile_id  uuid not null references public.profiles (id) on delete cascade,
  name        citext not null,
  held_from   timestamptz not null,
  released_at timestamptz not null default now()
);

create index name_history_name on public.name_history (name, released_at desc);
create index name_history_profile on public.name_history (profile_id, released_at desc);

alter table public.name_history enable row level security;
-- No policies at all, deliberately: with RLS on and nothing granted, the table
-- is invisible to anon and authenticated no matter what future query is written.

/**
 * Has this name been somebody else's recently?
 *
 * Returns when it was released, or null. Never returns who — a profile that
 * published "was xXx_420 until tuesday" would make renaming pointless for the
 * exact person §4.6 is written for.
 */
create or replace function public.name_changed_hands (p_name citext)
returns timestamptz
language sql
stable
security definer
set search_path = public
as $$
  select max(h.released_at)
    from public.name_history h
   where h.name = p_name
     and h.released_at > now() - interval '90 days'
     -- Somebody has to be holding it *now*, and it has to be somebody else.
     -- A name lying unclaimed has not changed hands, and renaming away from a
     -- name and back to it is not a change of hands either.
     and exists (
       select 1 from public.profiles p
        where p.name = p_name and p.id <> h.profile_id
     );
$$;

grant execute on function public.name_changed_hands (citext) to anon, authenticated;

/**
 * The rename itself.
 *
 * security definer, and no UPDATE grant on profiles anywhere, so this is the
 * only way a name can change — which is what makes "record the old one" and
 * "you cannot do this while banned" impossible to route around.
 */
create or replace function public.change_name (p_name citext)
returns citext
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_id      uuid := auth.uid ();
  v_current citext;
  v_since   timestamptz;
  v_banned  timestamptz;
  v_recent  integer;
begin
  if v_id is null then
    raise exception 'you have to be signed in to change your name'
      using errcode = 'insufficient_privilege';
  end if;

  select name, name_since, banned_at into v_current, v_since, v_banned
    from public.profiles where id = v_id;

  if v_current is null then
    raise exception 'you do not have a name yet' using errcode = 'no_data_found';
  end if;

  if v_banned is not null then
    raise exception 'you can''t say things here anymore.'
      using errcode = 'insufficient_privilege';
  end if;

  if v_current = p_name then
    raise exception 'that is already your name' using errcode = 'check_violation';
  end if;

  -- Not a cap on how many times you may rename — it is flood protection, the
  -- same as the one on posting. Cycling a name a hundred times an hour is the
  -- only thing this stops, and that is not somebody fixing a 2am mistake.
  select count(*) into v_recent
    from public.name_history
   where profile_id = v_id
     and released_at > now() - interval '1 hour';

  if v_recent >= 5 then
    raise exception 'that is a lot of names in an hour — give it a while'
      using errcode = 'check_violation';
  end if;

  -- Written before the update so that a unique violation on the new name rolls
  -- the history row back with it. A recorded release of a name you still hold
  -- would make it look like it changed hands.
  insert into public.name_history (profile_id, name, held_from)
  values (v_id, v_current, v_since);

  update public.profiles
     set name = p_name, name_since = now()
   where id = v_id;

  return p_name;
exception
  -- The handler rolls the block back, so the history row goes with the failed
  -- update rather than recording the release of a name they still hold.
  when unique_violation then
    raise exception '% is taken', p_name using errcode = 'unique_violation';
end;
$$;

revoke all on function public.change_name (citext) from public, anon;
grant execute on function public.change_name (citext) to authenticated;

;


-- ==========================================================================
-- 20260804040000_erasure.sql
-- ==========================================================================

-- The right to be forgotten, on a schema where deleting the row is the wrong
-- answer.
--
-- `profiles.id` references `auth.users` on delete cascade, and posts and replies
-- reference profiles the same way. So "delete the account" removes every reply
-- other people wrote under their posts, which is somebody else's speech being
-- deleted to satisfy a request that was never about it.
--
-- Erasure is therefore anonymisation, which is what the regulation asks for
-- anyway: the personal data goes — the address, and the handle that identifies
-- them — and the contributions stay, attached to a handle that is nobody. If
-- the person also wants what they said taken down, that is `ban` with post
-- hiding, a separate lever they have to ask for separately.

create or replace function public.forget (p_name citext)
returns citext
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_id       uuid;
  v_tombname citext;
begin
  select id into v_id from public.profiles where name = p_name;
  if v_id is null then
    raise exception 'no one called %', p_name using errcode = 'no_data_found';
  end if;

  -- Short and random rather than sequential: `deleted_1` next to `deleted_2`
  -- tells you the order people left, which is information about them.
  --
  -- md5 rather than gen_random_bytes because pgcrypto lives in the `extensions`
  -- schema on a hosted project and this function pins search_path to public.
  v_tombname := 'deleted_' || substr(md5(random()::text || clock_timestamp()::text), 1, 8);

  -- Every handle they have ever held goes, including the ones in the history
  -- table. Leaving those behind would let name_changed_hands point back at a
  -- person who asked to be gone.
  delete from public.name_history where profile_id = v_id;

  update public.profiles
     set name          = v_tombname,
         name_since    = now(),
         banned_at     = now(),
         banned_reason = 'account closed',
         verified_at   = null
   where id = v_id;

  -- The address is the personal datum that matters most, and it lives in
  -- auth.users rather than here. Overwritten rather than nulled: GoTrue reads
  -- these columns as non-nullable strings, and a null breaks sign-in for
  -- everybody rather than just this row.
  --
  -- On a hosted project auth.users is owned by supabase_auth_admin, which may
  -- refuse this. A half-finished erasure that reported success would be the
  -- worst outcome available, so it warns loudly and names the other route
  -- rather than failing silently or rolling the anonymisation back.
  begin
    update auth.users
       set email              = v_tombname || '@deleted.invalid',
           raw_user_meta_data = '{}'::jsonb,
           raw_app_meta_data  = '{}'::jsonb
     where id = v_id;
  exception
    when insufficient_privilege then
      raise warning 'THE ADDRESS WAS NOT ERASED: this role may not write auth.users. Delete user % through the Auth admin API to finish.', v_id;
  end;

  return v_tombname;
end;
$$;

revoke all on function public.forget (citext) from public, anon, authenticated;

do $$
begin
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    grant execute on function public.forget (citext) to service_role;
  end if;
end
$$;

;


-- ==========================================================================
-- 20260804050000_walls.sql
-- ==========================================================================

-- Walls — §3.10, reversed on purpose.
--
-- The doc's most emphatic architectural warning is that a space which absorbs
-- activity "deletes the geography that makes this feel like a place", and
-- profiles were built as a view for exactly that reason. This adds the place
-- back, deliberately, because the site is called thewall and somewhere to put
-- your own things is what people asked for.
--
-- The shape is chosen so the warning still has teeth: **a wall is a room**. It
-- is not a new kind of object with its own posting rules, its own addresses and
-- its own moderation story — it is a row in `rooms` with an owner, so the
-- allocator, the reply trigger, the expiry policy, mail, search and every lever
-- in scripts/moderate.sh apply to it already and cannot drift away from it.
--
-- The one thing walls do not get is a place in the lobby. §4.2 is blunt that
-- forty rooms with three people each kills the feeling, and a room per person
-- is precisely that — so `room_overview` keeps showing the six curated rooms
-- and nothing else. A wall is reached through its owner, never by browsing.

alter table public.rooms
  add column owner_id uuid references public.profiles (id) on delete cascade;

comment on column public.rooms.owner_id is
  'Whose wall this is. Null for the curated rooms, which belong to nobody.';

-- One wall each. Not a policy, a fact about what a wall is.
create unique index rooms_owner on public.rooms (owner_id) where owner_id is not null;

-- `~marisol`. The tilde is already how the product says "a person" in a path
-- and in the prompt (§3.4), so a wall's address needs no new vocabulary.
alter table public.rooms drop constraint rooms_slug_shape;
alter table public.rooms add constraint rooms_slug_shape check (
  slug ~ '^[a-z0-9-]{2,24}$' or slug ~ '^~[a-z0-9_]{2,20}$'
);

-- The two halves cannot come apart: a room with an owner is a wall and looks
-- like one, and a room without an owner is a room and does not.
alter table public.rooms add constraint rooms_wall_shape check (
  (owner_id is null and slug !~ '^~') or (owner_id is not null and slug ~ '^~')
);

-- A rename has to take the wall with it, or `/~newname` is empty and the posts
-- are stranded at an address nobody can reach. The address is a name, and names
-- move (§4.6) — so the foreign key has to allow the slug to move too.
alter table public.posts drop constraint posts_room_slug_fkey;
alter table public.posts add constraint posts_room_slug_fkey
  foreign key (room_slug) references public.rooms (slug) on update cascade on delete cascade;

create or replace function public.change_name (p_name citext)
returns citext
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_id      uuid := auth.uid ();
  v_current citext;
  v_since   timestamptz;
  v_banned  timestamptz;
  v_recent  integer;
begin
  if v_id is null then
    raise exception 'you have to be signed in to change your name'
      using errcode = 'insufficient_privilege';
  end if;

  select name, name_since, banned_at into v_current, v_since, v_banned
    from public.profiles where id = v_id;

  if v_current is null then
    raise exception 'you do not have a name yet' using errcode = 'no_data_found';
  end if;

  if v_banned is not null then
    raise exception 'you can''t say things here anymore.'
      using errcode = 'insufficient_privilege';
  end if;

  if v_current = p_name then
    raise exception 'that is already your name' using errcode = 'check_violation';
  end if;

  select count(*) into v_recent
    from public.name_history
   where profile_id = v_id
     and released_at > now() - interval '1 hour';

  if v_recent >= 5 then
    raise exception 'that is a lot of names in an hour — give it a while'
      using errcode = 'check_violation';
  end if;

  insert into public.name_history (profile_id, name, held_from)
  values (v_id, v_current, v_since);

  update public.profiles
     set name = p_name, name_since = now()
   where id = v_id;

  -- The wall follows the name. Cascading on the foreign key above is what keeps
  -- every post on it addressable at the new one.
  update public.rooms set slug = '~' || p_name where owner_id = v_id;

  return p_name;
exception
  when unique_violation then
    raise exception '% is taken', p_name using errcode = 'unique_violation';
end;
$$;

revoke all on function public.change_name (citext) from public, anon;
grant execute on function public.change_name (citext) to authenticated;

-- The lobby ------------------------------------------------------------------
-- Unchanged except for the one clause that matters: walls are not rooms you
-- browse to. §3.11's proof of life is about a building with six doors, and a
-- door per person is a directory.
create or replace view public.room_overview
with (security_invoker = true) as
select
  r.slug,
  r.gloss,
  r.ephemeral,
  r.sort_order,
  latest.body       as latest_body,
  latest.created_at as latest_at,
  author.name       as latest_author
from public.rooms r
left join lateral (
  select p.body, p.created_at, p.author_id
    from public.posts p
   where p.room_slug = r.slug
     and p.hidden_at is null
     and public.is_visible (p.room_slug, p.created_at)
   order by p.created_at desc
   limit 1
) latest on true
left join public.profiles author on author.id = latest.author_id
where r.hidden_at is null
  and r.archived_at is null
  and r.owner_id is null;

-- Posting --------------------------------------------------------------------

create or replace function public.create_post (p_room citext, p_body text)
returns public.posts
language plpgsql
security definer
set search_path = public
as $$
declare
  v_post_no integer;
  v_post    public.posts;
  v_owner   uuid;
  v_exists  boolean;
  v_name    citext;
begin
  if auth.uid () is null then
    raise exception 'you have to be signed in to say something'
      using errcode = 'insufficient_privilege';
  end if;

  perform public.require_can_contribute (auth.uid ());

  select owner_id, true into v_owner, v_exists
    from public.rooms where slug = p_room;

  -- Your own wall, made the first time you put something on it. Creating it at
  -- signup instead would leave everybody with an empty room they never asked
  -- for, and §5 is blunt that an empty room is worse than no room.
  if not coalesce(v_exists, false) and p_room ~ '^~' then
    select name into v_name from public.profiles where id = auth.uid ();
    if v_name is null or p_room <> ('~' || v_name)::citext then
      raise exception 'no room called %', p_room using errcode = 'no_data_found';
    end if;

    insert into public.rooms (slug, gloss, ephemeral, sort_order, owner_id)
    values (p_room, 'what ' || v_name || ' is saying', false, 1000, auth.uid ());
    v_owner := auth.uid ();
  end if;

  -- Somebody else's wall is theirs to start things on. Replying is open to
  -- everyone, which is the whole point of it being a wall rather than a diary —
  -- and that goes through the replies table, not through here.
  if v_owner is not null and v_owner <> auth.uid () then
    raise exception 'this is somebody else''s wall — you can reply to what is here, but only they can post to it'
      using errcode = 'insufficient_privilege';
  end if;

  update public.rooms
     set next_post_no = next_post_no + 1,
         archived_at  = null
   where slug = p_room
     and hidden_at is null
  returning next_post_no - 1 into v_post_no;

  if v_post_no is null then
    raise exception 'no room called %', p_room using errcode = 'no_data_found';
  end if;

  insert into public.posts (room_slug, post_no, author_id, body)
  values (p_room, v_post_no, auth.uid (), p_body)
  returning * into v_post;

  return v_post;
end;
$$;

revoke all on function public.create_post (citext, text) from public;
grant execute on function public.create_post (citext, text) to authenticated;

-- Decay skips walls: a quiet wall is a person who has not posted lately, which
-- is not a room going cold and is nobody's business to tidy up (§4.2).
create or replace function public.archive_quiet_rooms (p_idle interval default interval '7 days')
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_count integer;
begin
  update public.rooms r
     set archived_at = now()
   where r.archived_at is null
     and r.hidden_at is null
     and not r.ephemeral
     and r.owner_id is null
     and not exists (
       select 1 from public.posts p
        where p.room_slug = r.slug
          and p.hidden_at is null
          and p.created_at > now() - p_idle
     );
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;

;


-- ==========================================================================
-- 20260805000000_user_rooms.sql
-- ==========================================================================

-- User-created rooms, against §4.2.
--
-- §4.2 is unambiguous: "a fixed, curated set at launch. room creation stays
-- closed", because "40 rooms with three people each kills the entire feeling".
-- That is decided differently here, by the person whose site it is, and the
-- doc's warning is still right about the thing it is actually about.
--
-- Read the warning carefully and it is not about how many rooms exist. It is
-- about the room *list* — the first impression, the thing that has to read as a
-- building rather than a directory. A room nobody is in does no harm sitting in
-- the database; it does harm sitting in the lobby. So creation opens and the
-- lobby stays curated:
--
--   * anybody verified may make a room, three a week;
--   * the six curated rooms always show, in their curated order;
--   * a user room shows only while it has life in it, and fades out quietly
--     when it does not — reachable forever by name and by search, just not
--     taking up the shop window.
--
-- The fade is §4.2's own decay rule, which has been "written but not enabled"
-- since it was first added. It is enabled here, and by a clause in the lobby
-- query rather than by a scheduled job: nobody is running cron for this, and a
-- decay rule that needs a cron nobody set up is a decay rule that never runs.
-- `archive_quiet_rooms` stays exactly what it was, a manual lever.

-- Who made it ----------------------------------------------------------------
--
-- Separate from owner_id, which means "this is that person's wall" and carries
-- a unique index and a `~` slug with it. This is only a record of who opened
-- the door.
--
-- `on delete set null` and not cascade, deliberately. A room outlives the
-- person who made it, because by then the conversations in it belong to
-- everybody who turned up. Cascading would delete other people's posts to
-- satisfy one person leaving, which is the same mistake `forget` exists to
-- avoid.
alter table public.rooms
  add column created_by uuid references public.profiles (id) on delete set null;

comment on column public.rooms.created_by is
  'who opened it. null means curated — seeded, or opened by the operator.';

create index rooms_created_by on public.rooms (created_by) where created_by is not null;

-- Whether it is furniture, as its own fact.
--
-- The lobby first read this as `created_by is null`, which is the same thing
-- until it is not: `created_by` is `on delete set null`, so erasing the person
-- who opened a room would silently promote their room to a curated one — a
-- permanent fixture in the lobby that no longer fades and that nobody chose.
-- The two questions are different and deserve two columns.
alter table public.rooms
  add column curated boolean not null default false;

comment on column public.rooms.curated is
  'true for the seeded rooms and anything the operator opens: always in the lobby, never faded.';

-- Everything that exists at this point predates user-created rooms, so all of
-- it is curated by definition.
update public.rooms set curated = true where owner_id is null;

-- Who made it is not public --------------------------------------------------
--
-- `grant select on public.rooms` is table-wide, so adding created_by handed
-- every column of it to anon and authenticated alike: one line in a browser
-- console and you have the account id behind every room on the site. It is
-- shown nowhere in the interface, and "a room has no owner" is supposed to be
-- true of the data and not merely of the UI.
--
-- This is the same shape as the bug that made `verified_at` settable from the
-- console — a table-wide grant beside a row policy, where the policy answers
-- "whose row" and nothing answers "which columns". Column-scoped, then, and
-- created_by is simply not in the list. The lobby reads `curated` instead,
-- which is a boolean about the room rather than a fact about a person.
revoke select on public.rooms from anon, authenticated;
grant select (
  slug, gloss, ephemeral, sort_order, next_post_no, created_at,
  hidden_at, archived_at, owner_id, curated
) on public.rooms to anon, authenticated;

-- Names nobody may take ------------------------------------------------------
--
-- Every one of these is a real path under app/. A room called `terms` would be
-- shadowed by /terms forever: `go terms` would work, thewall.social/terms would
-- not, and §3.4's "the prompt path is the URL" would be quietly false for one
-- room. It is a table rather than a constant so adding a route means adding a
-- row, and so the message can name the reason.
create table public.reserved_slugs (
  slug   citext primary key,
  reason text not null
);

alter table public.reserved_slugs enable row level security;
create policy "anyone may read reserved slugs"
  on public.reserved_slugs for select using (true);
grant select on public.reserved_slugs to anon, authenticated;

insert into public.reserved_slugs (slug, reason) values
  ('lobby',           'the lobby lives there'),
  ('api',             'that is a route'),
  ('auth',            'that is a route'),
  ('legal',           'that is a route'),
  ('terms',           'that is a route'),
  ('privacy',         'that is a route'),
  ('icon',            'that is a route'),
  ('apple-icon',      'that is a route'),
  ('opengraph-image', 'that is a route')
on conflict (slug) do nothing;

-- Making one -----------------------------------------------------------------
--
-- security definer, because `authenticated` has select on rooms and nothing
-- else and that stays true: this function is the only door, so every rule below
-- is unroutable-around rather than a policy somebody has to get right twice.
--
-- VOLATILE. A stable function sees the snapshot from the start of the
-- statement, and `select create_room(...) from generate_series(1, 25)` would
-- have every call observe "you have made no rooms this week" — which is exactly
-- how the §4.7 one-contribution gate was defeated before anybody noticed.
create or replace function public.create_room (p_slug citext, p_gloss text)
returns citext
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_id      uuid := auth.uid ();
  v_ok      boolean;
  v_banned  boolean;
  v_reason  text;
  v_made    integer;
  v_oldest  timestamptz;
  v_wait    integer;
  v_gloss   text := btrim(p_gloss);
  v_slug    citext := lower(btrim(p_slug::text))::citext;
begin
  if v_id is null then
    raise exception 'you need a name before you can make a room'
      using errcode = 'insufficient_privilege';
  end if;

  -- Verified, not merely named. §4.7 lets an unverified account have one
  -- contribution so the held sentence lands; a room is not that. It is a
  -- permanent address in a shared space, and the cost of making one has to be
  -- an inbox somebody actually reads.
  select p.verified_at is not null, p.banned_at is not null
    into v_ok, v_banned
    from public.profiles p where p.id = v_id;

  -- Banned first, and said plainly. Folding it into the verified check told a
  -- banned account to go and check its email, which is a message that sends
  -- somebody looking for a link that will not help them.
  if coalesce(v_banned, false) then
    raise exception 'this account cannot post here.'
      using errcode = 'insufficient_privilege';
  end if;

  if not coalesce(v_ok, false) then
    raise exception 'check your email first — a room is permanent, so it wants a verified account. no link? type resend.'
      using errcode = 'insufficient_privilege';
  end if;

  -- Three a week. §4.2's failure is a lobby that fills faster than it empties,
  -- and the cap is what keeps one enthusiastic evening from being fifteen
  -- rooms — while leaving room for somebody who actually has three ideas.
  --
  -- A rolling window, not a calendar week. A week that resets at midnight on
  -- Sunday hands everybody three fresh rooms at the same moment, which is the
  -- one time you would least like it to.
  select count(*), min(created_at)
    into v_made, v_oldest
    from public.rooms
   where created_by = v_id
     and created_at > now() - interval '7 days';

  if v_made >= 3 then
    -- Whole days, rounded up. `justify_interval` renders
    -- "6 days 23:59:59.873763", which is a debug dump rather than an answer to
    -- "when can I make another one".
    v_wait := ceil(extract(epoch from (v_oldest + interval '7 days' - now())) / 86400);
    raise exception 'that is three rooms this week, which is the limit. you can make another %, and rooms are easier to make than to fill.',
      case when v_wait <= 1 then 'tomorrow' else 'in ' || v_wait || ' days' end
      using errcode = 'too_many_rows';
  end if;

  if v_slug ~ '^~' then
    raise exception '~ names a wall, and you already have one. pick a plain name.'
      using errcode = 'check_violation';
  end if;

  if v_slug !~ '^[a-z0-9-]{2,24}$' then
    raise exception 'a room name is 2 to 24 characters of a-z, 0-9 and -. nothing else, and no spaces.'
      using errcode = 'check_violation';
  end if;

  select reason into v_reason from public.reserved_slugs where slug = v_slug;
  if v_reason is not null then
    raise exception '% is spoken for — %.', v_slug, v_reason
      using errcode = 'check_violation';
  end if;

  if exists (select 1 from public.rooms where slug = v_slug) then
    raise exception '% already exists. try: go %', v_slug, v_slug
      using errcode = 'unique_violation';
  end if;

  -- Somebody's name is not available as a room.
  --
  -- `go marisol` and `go ~marisol` are already different addresses, so nothing
  -- breaks — but a room called `marisol` sits in the lobby under her name, with
  -- a gloss its maker chose, and §4.6's whole argument about impersonation is
  -- that it is aimed at the reader. The reader is who this protects.
  if exists (select 1 from public.profiles where name = v_slug) then
    raise exception '% is somebody''s name. try: go ~% to see them.', v_slug, v_slug
      using errcode = 'unique_violation';
  end if;

  -- §3.6 and §3.11 both rest on the gloss: the lobby reads as a building
  -- because every door says what is behind it. A room without one is a slug in
  -- a list, so it is required rather than optional, and short enough to fit the
  -- one line it gets at 380px.
  if char_length(v_gloss) < 3 or char_length(v_gloss) > 60 then
    raise exception 'say what it is for, in a few words — that is the line under the name in the lobby.'
      using errcode = 'check_violation';
  end if;

  -- sort_order is not read for a user room: the lobby orders those by life,
  -- not by curation. Set past the curated block anyway so nothing collides if
  -- the operator ever promotes one.
  insert into public.rooms (slug, gloss, ephemeral, sort_order, created_by)
  values (v_slug, v_gloss, false, 500, v_id);

  return v_slug;
end;
$$;

revoke all on function public.create_room (citext, text) from public, anon;
grant execute on function public.create_room (citext, text) to authenticated;

-- The lobby ------------------------------------------------------------------
--
-- Two changes: it says whether a room is curated, and a user room drops out of
-- it once nothing has been said there for a fortnight.
--
-- The fade is measured from the newest post, or from when the room was made if
-- there is nothing in it yet — so a room made this morning is in the lobby this
-- morning, which is the whole of its chance to find anybody. §5's "an empty
-- room is worse than no room" is why that grace is two weeks and not forever.
--
-- Nothing here hides anything. A faded room answers to its name, keeps its
-- posts and its addresses, appears in search, and comes straight back the
-- moment somebody says something in it.
create or replace view public.room_overview
with (security_invoker = true) as
select
  r.slug,
  r.gloss,
  r.ephemeral,
  r.sort_order,
  latest.body       as latest_body,
  latest.created_at as latest_at,
  author.name       as latest_author,
  -- Appended rather than slotted in beside sort_order, where it reads better:
  -- `create or replace view` may only add columns at the end, and reordering
  -- would mean dropping the view — which on a security_invoker view means
  -- dropping the thing every anonymous lobby read depends on, mid-migration.
  r.curated
from public.rooms r
left join lateral (
  select p.body, p.created_at, p.author_id
    from public.posts p
   where p.room_slug = r.slug
     and p.hidden_at is null
     and public.is_visible (p.room_slug, p.created_at)
   order by p.created_at desc
   limit 1
) latest on true
left join public.profiles author on author.id = latest.author_id
where r.hidden_at is null
  and r.archived_at is null
  and r.owner_id is null
  and (
    r.curated
    or coalesce(latest.created_at, r.created_at) > now() - interval '14 days'
  );

-- Finding a room -------------------------------------------------------------
--
-- Once rooms multiply, "which rooms are there" stops being answered by looking
-- at the lobby, and a room nobody can find is a room that dies. Name and gloss
-- both, because half the time you remember what a room was *for* and not what
-- it was called.
--
-- Faded and archived rooms are included on purpose: this is the way back to
-- one. Hidden rooms are not — `close` means gone.
create or replace function public.find_rooms (p_term text, p_limit integer default 20)
returns table (
  slug        citext,
  gloss       text,
  curated     boolean,
  in_lobby    boolean,
  latest_at   timestamptz,
  post_count  bigint
)
language sql
stable
security definer
set search_path = public
as $$
  select
    r.slug,
    r.gloss,
    r.curated,
    r.archived_at is null and (
      r.curated
      or coalesce(newest.at, r.created_at) > now() - interval '14 days'
    ),
    newest.at,
    coalesce(counted.n, 0)
  from public.rooms r
  left join lateral (
    select max(p.created_at) as at
      from public.posts p
     where p.room_slug = r.slug and p.hidden_at is null
  ) newest on true
  left join lateral (
    select count(*) as n
      from public.posts p
     where p.room_slug = r.slug and p.hidden_at is null
  ) counted on true
  where r.hidden_at is null
    and r.owner_id is null
    and (
      p_term is null
      or btrim(p_term) = ''
      -- `like` with the term escaped, not ilike with it interpolated: a search
      -- for "100%" must not become a wildcard that matches every room.
      or r.slug::text ilike '%' || replace(replace(replace(btrim(p_term), '\', '\\'), '%', '\%'), '_', '\_') || '%' escape '\'
      or r.gloss ilike '%' || replace(replace(replace(btrim(p_term), '\', '\\'), '%', '\%'), '_', '\_') || '%' escape '\'
    )
  order by r.curated desc, newest.at desc nulls last, r.slug
  limit greatest(1, least(coalesce(p_limit, 20), 50));
$$;

grant execute on function public.find_rooms (text, integer) to anon, authenticated;

-- Searching what was said ----------------------------------------------------
--
-- `find` has always read the posts table directly from the client and has
-- always therefore missed every reply — which on a site whose §4.3 shape is
-- "post, then a flat list of answers" is most of what anybody says. This is one
-- query over both, so a reply is findable and carries the address of the post
-- it is under.
--
-- Walls are searchable, and commons is not: an ephemeral room has no permanent
-- address, so a hit there would be somewhere you cannot go (§3.10).
create or replace function public.search_said (
  p_text  text default null,
  p_room  citext default null,
  p_by    citext default null,
  p_since timestamptz default null,
  p_limit integer default 20
)
returns table (
  room       citext,
  post_no    integer,
  author     citext,
  body       text,
  created_at timestamptz,
  is_reply   boolean
)
language sql
stable
security definer
set search_path = public
as $$
  with term as (
    select case
             when p_text is null or btrim(p_text) = '' then null
             else '%' || replace(replace(replace(btrim(p_text), '\', '\\'), '%', '\%'), '_', '\_') || '%'
           end as pattern
  ),
  said as (
    select p.room_slug as room, p.post_no, a.name as author, p.body, p.created_at,
           false as is_reply
      from public.posts p
      join public.rooms rm on rm.slug = p.room_slug
      join public.profiles a on a.id = p.author_id
     where p.hidden_at is null
       and rm.hidden_at is null
       and not rm.ephemeral

    union all

    select p.room_slug as room, p.post_no, a.name as author, r.body, r.created_at,
           true as is_reply
      from public.replies r
      join public.posts p on p.id = r.post_id
      join public.rooms rm on rm.slug = p.room_slug
      join public.profiles a on a.id = r.author_id
     where r.hidden_at is null
       -- A reply under a hidden post is hidden with it: the address it would
       -- send you to shows nothing, so a hit there is a dead end.
       and p.hidden_at is null
       and rm.hidden_at is null
       and not rm.ephemeral
  )
  select said.room, said.post_no, said.author, said.body, said.created_at, said.is_reply
    from said, term
   where (term.pattern is null or said.body ilike term.pattern escape '\')
     and (p_room  is null or said.room = p_room)
     and (p_by    is null or said.author = p_by)
     and (p_since is null or said.created_at >= p_since)
   order by said.created_at desc
   limit greatest(1, least(coalesce(p_limit, 20), 50));
$$;

grant execute on function public.search_said (text, citext, citext, timestamptz, integer) to anon, authenticated;

-- Indexes for the two searches above. Both were sequential scans over every
-- post on the site, which is fine at six rooms and is the first thing to hurt
-- once rooms are something people make.
create index if not exists posts_created_at on public.posts (created_at desc);
create index if not exists replies_created_at on public.replies (created_at desc);

;


-- ==========================================================================
-- 20260805010000_terms_accepted.sql
-- ==========================================================================

-- Recording that somebody agreed, and to what.
--
-- The terms said "Using it means agreeing to what is below", and nothing on the
-- site had ever mentioned them. That is browsewrap: no notice, no moment of
-- assent, nothing recorded. US courts — and the governing law is now a US state
-- — have thrown browsewrap out repeatedly for exactly that, and the reasoning
-- is not a technicality. Somebody who was never shown the terms did not agree
-- to them, and saying they did on a page they also never saw does not fix it.
--
-- The fix has to survive §6's "there is no form anywhere". So it is sign-in
-- wrap: at the one moment somebody is deliberately creating an account, the
-- prompt says plainly that this means agreeing, names the command that shows
-- them, and waits for an answer that is a positive act. Then this records it.
--
-- Two columns and not one. "They agreed" is nearly useless a year later when
-- the document has changed twice; "they agreed to the 5 August 2026 version" is
-- the thing that can actually be stood behind. Retention follows the account,
-- because a record of consent outliving the account it belongs to would be its
-- own privacy problem.
alter table public.profiles
  add column terms_accepted_at timestamptz,
  add column terms_version     text;

comment on column public.profiles.terms_accepted_at is
  'when this account was created, which is when the terms were agreed to. null for accounts made before there was a moment of assent to record.';

comment on column public.profiles.terms_version is
  'the LAST_UPDATED string of the terms as they stood at that moment.';

-- Deliberately left null for everybody who already exists.
--
-- Backfilling it with now() would be inventing evidence: those accounts were
-- made when nothing asked, and writing a timestamp against them would say they
-- were shown something they were not. Null is the truthful value, and it says
-- exactly which accounts predate the change.

-- Nothing grants a browser the ability to write these. There is no UPDATE grant
-- on `profiles` for `authenticated` at all — that was revoked when the same
-- shape let anybody set their own `verified_at` — and the insert happens in the
-- signup route under the service role. A consent record a user can forge is not
-- a consent record.
--
-- The columns are readable, which is deliberate: it is your own data, and
-- "what did I agree to and when" is a question somebody is entitled to ask.
-- Nothing in the interface shows it for anybody else, and the row-level policy
-- on profiles is unchanged.

;


-- ==========================================================================
-- 20260805020000_mail_respects_hiding.sql
-- ==========================================================================

-- Mail was the one place the kill switch did not reach.
--
-- `mail()` and `mail_count()` joined replies to posts and filtered on who wrote
-- them, and on nothing else. Neither looked at `hidden_at` — not on the reply,
-- not on the post it hangs under, not on the room it is in. So hiding a post,
-- hiding a reply, or banning somebody (which hides everything they wrote) left
-- every one of those replies sitting in other people's inboxes, still counted in
-- the badge, still delivered on `mail`.
--
-- That is the exact failure §6's manual kill switch exists to prevent, on the
-- one surface that reaches out and taps somebody on the shoulder. Everywhere
-- else — the room listing, a post, search, a profile — hiding worked.
--
-- The lever is used at the moment somebody is being harassed, so "the abuse is
-- gone from the site but still arrives in your notifications" is close to the
-- worst version of getting this wrong.

create or replace function public.mail ()
returns table (
  room       citext,
  post_no    integer,
  author     citext,
  body       text,
  created_at timestamptz
)
language sql
stable
security definer
set search_path = public
as $$
  select p.room_slug, p.post_no, author.name, r.body, r.created_at
    from public.replies r
    join public.posts p on p.id = r.post_id
    join public.rooms rm on rm.slug = p.room_slug
    join public.profiles author on author.id = r.author_id
   where p.author_id = auth.uid ()
     and r.author_id <> auth.uid ()
     -- The reply itself, the post it is under, and the room both are in. A
     -- reply under a hidden post is a notification pointing at nothing, and a
     -- closed room is gone for everybody including the person being notified.
     and r.hidden_at is null
     and p.hidden_at is null
     and rm.hidden_at is null
     and r.created_at > (select mail_seen_at from public.profiles where id = auth.uid ())
   order by r.created_at desc
   -- Raised from 50. Reading is what marks mail read, and with newest-first
   -- ordering anything past the cap is older than everything shown — so a cap
   -- that is hit quietly clears replies nobody ever saw. It cannot be avoided
   -- without a per-reply read model, so it is made rarer here and said out loud
   -- in the command when the cap is reached.
   limit 100;
$$;

create or replace function public.mail_count ()
returns integer
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(count(*), 0)::integer
    from public.replies r
    join public.posts p on p.id = r.post_id
    join public.rooms rm on rm.slug = p.room_slug
   where p.author_id = auth.uid ()
     and r.author_id <> auth.uid ()
     and r.hidden_at is null
     and p.hidden_at is null
     and rm.hidden_at is null
     and r.created_at > (select mail_seen_at from public.profiles where id = auth.uid ());
$$;

-- The count and the listing have to agree, or the badge says 3 and `mail` shows
-- 1. They are separate functions because one is polled and the other is not, so
-- the filters above are the same filters twice on purpose.

;


-- ==========================================================================
-- 20260805030000_about_is_a_route.sql
-- ==========================================================================

-- /about is a page now, so nobody may take it as a room name.
--
-- In its own migration rather than added to the insert that created the table:
-- that one may already be applied, and a row added to an applied file never
-- runs. This is the rule `CHANGING-IT.md` states for adding a route, followed.
--
-- A room called `about` would be shadowed by the page forever — `go about`
-- would work, thewall.social/about would not be the room, and §3.4's "the
-- prompt path is the URL" would be quietly false for exactly one room.
insert into public.reserved_slugs (slug, reason)
values ('about', 'that is a route')
on conflict (slug) do nothing;

;


-- ==========================================================================
-- 20260805040000_feed.sql
-- ==========================================================================

-- feed — everything people are putting on their own walls, in one place.
--
-- Walls are deliberately absent from the lobby: §4.2's "forty rooms with three
-- people each kills the entire feeling" is exactly what a door per person does
-- to a room list. That mitigation worked, and it left a hole. A wall is only
-- ever found by already knowing whose it is, so anything said on one reaches
-- the people who thought to go and look, which for most walls is nobody.
--
-- feed closes it without reopening the thing §4.2 warned about: one room, in
-- the lobby, holding what is on every wall — so the walls stay out of the
-- listing and what is said on them does not go unread.
--
-- It is a real room row rather than a client-side invention, so that /feed is
-- an address, the lobby lists it with a gloss like everything else, and search
-- finds it. What it is *not* is somewhere posts live: nothing is ever written
-- to feed, and the function below reads them from the walls they are on. Every
-- line in it carries a `~name/12` address that is the real one.

insert into public.rooms (slug, gloss, ephemeral, sort_order, curated)
values ('feed', 'what people are saying on their own walls', false, 6, true)
on conflict (slug) do nothing;

-- Curated, so it never fades out of the lobby, and sorted after the rooms that
-- were there first.
update public.rooms
   set curated = true, sort_order = 6, gloss = 'what people are saying on their own walls'
 where slug = 'feed';

insert into public.reserved_slugs (slug, reason)
values ('feed', 'that is the wall feed')
on conflict (slug) do nothing;

-- Nothing is ever posted into it -----------------------------------------------
--
-- feed is a view of walls. A post written *to* feed would sit in a room that
-- shows everything except itself, with an address nobody could reason about, so
-- create_post refuses it — and says the thing somebody meant, which is that
-- their own wall is where this goes.
create or replace function public.create_post (p_room citext, p_body text)
returns public.posts
language plpgsql
security definer
set search_path = public
as $$
declare
  v_post   public.posts;
  v_no     integer;
  v_exists boolean;
  v_owner  uuid;
  v_name   citext;
begin
  perform public.require_can_contribute (auth.uid ());

  if p_room = 'feed' then
    raise exception 'feed shows what people put on their own walls. put this on yours: go ~%',
      coalesce((select name from public.profiles where id = auth.uid ()), 'yourname')
      using errcode = 'insufficient_privilege';
  end if;

  select true, r.owner_id into v_exists, v_owner
    from public.rooms r where r.slug = p_room and r.hidden_at is null;

  -- A wall makes itself, on the first thing its owner puts there, and only for
  -- the owner's own name (see the walls migration).
  if not coalesce(v_exists, false) and p_room ~ '^~' then
    select name into v_name from public.profiles where id = auth.uid ();
    if v_name is null or p_room <> ('~' || v_name)::citext then
      raise exception 'no room called %', p_room using errcode = 'no_data_found';
    end if;

    insert into public.rooms (slug, gloss, ephemeral, sort_order, owner_id)
    values (p_room, 'what ' || v_name || ' is saying', false, 1000, auth.uid ());
    v_owner := auth.uid ();
    v_exists := true;
  end if;

  if not coalesce(v_exists, false) then
    raise exception 'no room called %', p_room using errcode = 'no_data_found';
  end if;

  if v_owner is not null and v_owner <> auth.uid () then
    raise exception 'this is somebody else''s wall — you can reply to what is here, but only they can post to it'
      using errcode = 'insufficient_privilege';
  end if;

  update public.rooms
     set next_post_no = next_post_no + 1,
         archived_at  = null
   where slug = p_room
  returning next_post_no - 1 into v_no;

  insert into public.posts (room_slug, post_no, author_id, body)
  values (p_room, v_no, auth.uid (), p_body)
  returning * into v_post;

  return v_post;
end;
$$;

revoke all on function public.create_post (citext, text) from public, anon;
grant execute on function public.create_post (citext, text) to authenticated;

-- Reading it -------------------------------------------------------------------
--
-- Every row carries the address it actually lives at, because that is the only
-- way back to it: post numbers are allocated per room, so `2` on the feed is
-- ambiguous and `~marisol/2` is not.
create or replace function public.wall_feed (p_limit integer default 40)
returns table (
  room       citext,
  post_no    integer,
  author     citext,
  body       text,
  created_at timestamptz,
  replies    bigint
)
language sql
stable
security definer
set search_path = public
as $$
  select p.room_slug, p.post_no, author.name, p.body, p.created_at,
         coalesce(counted.n, 0)
    from public.posts p
    join public.rooms r on r.slug = p.room_slug
    join public.profiles author on author.id = p.author_id
    left join lateral (
      select count(*) as n
        from public.replies rep
       where rep.post_id = p.id and rep.hidden_at is null
    ) counted on true
   -- Walls only. `owner_id is not null` is what makes a room one.
   where r.owner_id is not null
     and r.hidden_at is null
     and r.archived_at is null
     and p.hidden_at is null
     and author.banned_at is null
   order by p.created_at desc
   limit greatest(1, least(coalesce(p_limit, 40), 100));
$$;

grant execute on function public.wall_feed (integer) to anon, authenticated;

-- The lobby line for it --------------------------------------------------------
--
-- Without this the feed row has no posts of its own and the lobby says "quiet
-- in here" under it, which is both wrong and the §5 failure mode — a door that
-- advertises an empty room is worse than no door.
--
-- So the lateral that finds a room's newest post looks at walls when the row is
-- the feed, and at the room itself otherwise.
create or replace view public.room_overview
with (security_invoker = true) as
select
  r.slug,
  r.gloss,
  r.ephemeral,
  r.sort_order,
  latest.body       as latest_body,
  latest.created_at as latest_at,
  author.name       as latest_author,
  r.curated
from public.rooms r
left join lateral (
  select p.body, p.created_at, p.author_id
    from public.posts p
    join public.rooms pr on pr.slug = p.room_slug
   where (
           -- Same filters `wall_feed` uses, or the lobby advertises a post the
           -- feed itself will not show.
           (r.slug = 'feed' and pr.owner_id is not null
              and pr.hidden_at is null and pr.archived_at is null)
           or (r.slug <> 'feed' and p.room_slug = r.slug)
         )
     and p.hidden_at is null
     and public.is_visible (p.room_slug, p.created_at)
   order by p.created_at desc
   limit 1
) latest on true
left join public.profiles author on author.id = latest.author_id
where r.hidden_at is null
  and r.archived_at is null
  and r.owner_id is null
  and (
    r.curated
    or coalesce(latest.created_at, r.created_at) > now() - interval '14 days'
  );

;


-- ==========================================================================
-- 20260805050000_insert_grants.sql
-- ==========================================================================

-- The half of the column-scoping fix that was missed.
--
-- `20260804000000_column_scoped_grants.sql` closed this on UPDATE: a table-wide
-- grant beside a row policy means the policy answers "whose row is it" and
-- nothing answers "which columns may change", so anybody could set their own
-- `verified_at` and walk through the §4.7 gate.
--
-- INSERT was left table-wide, and it is the same hole. `profiles` has
-- `grant insert to authenticated` with a policy that checks only
-- `id = auth.uid()`, so a session with no profile row yet can create one with
-- **any column set**:
--
--   insert into profiles (id, name, verified_at, terms_accepted_at)
--   values (auth.uid(), 'attacker', now(), now())
--
-- and that account is verified without an inbox, may make rooms, and carries a
-- consent record it wrote itself. Verified against a real database before this
-- was written: `may_contribute` returned true immediately afterwards.
--
-- A session with no profile row is reachable. This app always creates the row
-- server-side under the service role, but the anon key can talk to GoTrue's own
-- signup and OTP endpoints directly, and those make a user and no profile.
--
-- I claimed in a commit message that the terms record "cannot be forged from a
-- browser, because there is no UPDATE grant on profiles". That was true of
-- UPDATE and false of the row's first write.

-- profiles ---------------------------------------------------------------------
--
-- Revoked outright rather than column-scoped. Nothing in the client inserts a
-- profile: signup does it through `createAdminClient()`, which is the service
-- role and bypasses grants entirely. A grant nothing uses is a grant that only
-- an attacker can find a use for.
revoke insert on public.profiles from authenticated;

-- replies ----------------------------------------------------------------------
--
-- This one is genuinely used by the client — `writer.ts` inserts
-- `{post_id, author_id, body}` — so it is scoped to exactly those three rather
-- than revoked.
--
-- What the table-wide version also allowed, both quieter than the profiles hole
-- and both real:
--
--   * `created_at` in the future. §4.1 counts a reply as unread while
--     `created_at > mail_seen_at`, so a reply dated next year sits in somebody's
--     inbox permanently and reading it does not clear it.
--   * `created_at` in the past, which reorders a thread: §4.3 sorts replies
--     chronologically, so a chosen timestamp puts your answer above answers
--     written before it.
--   * `hidden_at`, which is the operator's column and not a writer's.
revoke insert on public.replies from authenticated;
grant insert (post_id, author_id, body) on public.replies to authenticated;

-- The policy is unchanged and still does its half: `author_id = auth.uid()` and
-- the post has to be readable. Columns and rows are two different questions and
-- this schema now answers both on every table a browser can write to.

;


-- ==========================================================================
-- 20260806000000_three_more_rooms.sql
-- ==========================================================================

-- Two more permanent rooms, and a tidy-up of the order they sit in.
--
-- The curated set is the furniture (§3.11): rooms that are always there, never
-- fade out of the listing for going quiet, and make the lobby read the same way
-- each time you walk in. Anybody verified can make a room (§4.2 as revised),
-- but a room somebody makes drops out of the listing after a fortnight of
-- silence — these do not, and that is the entire difference.
--
-- crypto and movies were asked for by name. Both are ordinary topic rooms; the
-- only thing making them different from a room a person opens is `curated`.
--
-- Glosses follow §5's shape: a room is an invitation to tell somebody
-- something, not a category. "what you cooked" gets a story out of people in a
-- way "food" does not, so these are "what you are holding" and "what you
-- watched" rather than "cryptocurrency" and "film".

insert into public.rooms (slug, gloss, ephemeral, sort_order, curated) values
  ('crypto',   'what you are holding',                    false, 6, true),
  ('movies',   'what you watched',                        false, 7, true),
  -- The room about the site itself. Somewhere obvious to put "this is broken"
  -- matters more here than on most things: there is no support address on the
  -- page, no form, and no other way in — and a bug nobody can report is a bug
  -- that gets left rather than one that gets found.
  ('feedback', 'what is broken, and what should be here', false, 8, true)
on conflict (slug) do nothing;

-- `on conflict do nothing` means an existing row keeps whatever it had, which
-- for a room somebody had already made under one of these names would leave it
-- uncurated and fading. Stated separately so the outcome does not depend on
-- which of those two happened.
update public.rooms
   set curated = true, ephemeral = false
 where slug in ('crypto', 'movies', 'feedback');

update public.rooms set gloss = 'what you are holding', sort_order = 6 where slug = 'crypto';
update public.rooms set gloss = 'what you watched',    sort_order = 7 where slug = 'movies';
update public.rooms
   set gloss = 'what is broken, and what should be here', sort_order = 8
 where slug = 'feedback';

-- The order, set out in full ---------------------------------------------------
--
-- `feed` was on 6, which was last until this migration and would otherwise have
-- ended up in the middle of the topic rooms.
--
-- The rest matches the block at the end of the seed, which is the only thing
-- that has ever decided this: `seed.sql`'s *insert* has `poker` and `builders`
-- both on 2, and has since builders was added — harmless only because the
-- update underneath it fixes them. A live project seeded before this has the
-- fixed order already; one seeded and never re-run might not.
--
-- Written as one block rather than as edits to the two that moved, so the
-- answer to "what order is the lobby in" is this list and not this list plus
-- three previous migrations.
update public.rooms set sort_order = 0 where slug = 'commons';
update public.rooms set sort_order = 1 where slug = 'music';
update public.rooms set sort_order = 2 where slug = 'builders';
update public.rooms set sort_order = 3 where slug = 'poker';
update public.rooms set sort_order = 4 where slug = 'kitchen';
update public.rooms set sort_order = 5 where slug = 'latenight';
-- crypto 6, movies 7 and feedback 8 are set above.
update public.rooms set sort_order = 9 where slug = 'feed';

-- Every seeded room is curated. The column defaults to false, which is right
-- for a room somebody opens and wrong for every room in this list — and a
-- seeded room left unmarked would fade out of the lobby after a fortnight of
-- quiet, which is the one thing furniture must never do. Repeated from the seed
-- because the seed only ever runs on a fresh database.
update public.rooms
   set curated = true
 where owner_id is null
   and created_by is null;

;


-- ==========================================================================
-- 20260806010000_notify_optin.sql
-- ==========================================================================

-- One email a day, if you ask for it. Off for everybody until they do.
--
-- §4.1's lean was "pull-only, no push, no email", and it is decided differently
-- here for one reason: it also calls notifications the highest-priority unsolved
-- item, on the grounds that "no notification means no reason to return". Both
-- halves of that are true, and the way to keep them both is consent — nobody is
-- emailed who did not ask, and the people who did asked because they wanted a
-- reason to come back.
--
-- Everything lives in its own table rather than on `profiles`, and that is not
-- tidiness. `grant select on public.profiles` is table-wide, so a column added
-- there is readable by anyone with the anon key that ships in the browser
-- bundle. Three columns that must not be:
--
--   * the unsubscribe token — readable means anybody can unsubscribe anybody
--   * whether somebody gets email at all — nobody's business but theirs
--   * when they were last emailed — an activity trace on a site that publishes
--     a privacy policy saying it keeps none
--
-- So: a table with no grants and no policies, reached only through the
-- functions below. `profiles` stays exactly as public as it was.

create table if not exists public.notify_settings (
  profile_id  uuid primary key references public.profiles (id) on delete cascade,
  -- Off. Not "off unless", not "off for now" — the column default is the
  -- product decision, and a row only exists once somebody has chosen.
  daily       boolean     not null default false,
  -- The last time an email actually went out, which is what bounds this to one
  -- a day. Null means never.
  notified_at timestamptz,
  -- One per person, used in the link at the bottom of every digest. A uuid
  -- rather than the profile id, so possessing it proves nothing except that you
  -- were sent an email, and rotating it costs one update.
  token       uuid        not null default gen_random_uuid(),
  created_at  timestamptz not null default now()
);

create unique index if not exists notify_settings_token on public.notify_settings (token);

-- The job asks "who is due", which is a scan by flag and time.
create index if not exists notify_settings_due
  on public.notify_settings (daily, notified_at)
  where daily;

alter table public.notify_settings enable row level security;

-- No policies and no grants, deliberately. Every read and write below is
-- `security definer`, so there is exactly one door into this table and the
-- rules are in one place rather than split between a policy and a function.
revoke all on public.notify_settings from anon, authenticated;

-- Turning it on --------------------------------------------------------------
--
-- Verified only. An address nobody has proved they can read is an address that
-- probably belongs to somebody else (§4.7 is the same argument for posting), and
-- the one thing worse than not sending a digest is sending one to a stranger
-- whose address was typed into a signup box.
create or replace function public.set_notify (p_on boolean)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
  v_verified timestamptz;
begin
  if auth.uid () is null then
    raise exception 'you have to be signed in for that.';
  end if;

  select verified_at into v_verified from public.profiles where id = auth.uid ();

  if p_on and v_verified is null then
    raise exception 'follow the link in your email first — then i can send you things.';
  end if;

  insert into public.notify_settings (profile_id, daily)
  values (auth.uid (), p_on)
  on conflict (profile_id) do update set daily = excluded.daily;

  return p_on;
end;
$$;

-- Reading your own setting ----------------------------------------------------
create or replace function public.notify_state ()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(
    (select daily from public.notify_settings where profile_id = auth.uid ()),
    false
  );
$$;

revoke all on function public.set_notify (boolean) from public, anon;
revoke all on function public.notify_state () from public, anon;
grant execute on function public.set_notify (boolean) to authenticated;
grant execute on function public.notify_state () to authenticated;

-- Who is due ------------------------------------------------------------------
--
-- The unread count here is `mail_count()`'s, filter for filter, and it has to
-- stay that way: an email saying "3 replies" that opens onto an empty `mail` is
-- worse than no email. The difference is only that this runs for everybody at
-- once rather than for `auth.uid()`, which is why it cannot simply call it.
--
-- Twenty hours rather than twenty-four. A daily job never fires at exactly the
-- same second, and at 24 a run four minutes early skips somebody for the whole
-- day. At 20 the worst case is an email slightly less than a day after the last
-- one, which nobody will notice, and it still cannot produce two in a day
-- unless the job itself is run twice.
create or replace function public.pending_digests ()
returns table (
  profile_id uuid,
  name       citext,
  email      text,
  unread     integer,
  token      uuid
)
language sql
stable
security definer
set search_path = public
as $$
  select p.id,
         p.name,
         u.email::text,
         count(r.*)::integer,
         n.token
    from public.notify_settings n
    join public.profiles p on p.id = n.profile_id
    join auth.users u on u.id = p.id
    join public.posts po on po.author_id = p.id
    join public.rooms rm on rm.slug = po.room_slug
    join public.replies r on r.post_id = po.id
   where n.daily
     and p.banned_at is null
     and p.verified_at is not null
     and u.email is not null
     and (n.notified_at is null or n.notified_at < now() - interval '20 hours')
     -- The same three the badge uses: a reply under a hidden post, or in a
     -- closed room, is a notification pointing at nothing.
     and r.hidden_at is null
     and po.hidden_at is null
     and rm.hidden_at is null
     and r.author_id <> p.id
     and r.created_at > p.mail_seen_at
   group by p.id, p.name, u.email, n.token, n.notified_at
  /*
   * Two different questions, and the first version answered only one.
   *
   * `unread` is everything waiting, so the number in the email is the number in
   * the badge. Whether to send at all is a different question: has anything
   * arrived *since the last email*. Gating on unread alone meant somebody who
   * got a digest and never read their mail was sent the identical email every
   * day for as long as the pile sat there — which is precisely the daily nag
   * this feature is written to not be, and it contradicted the sentence the
   * command itself prints.
   *
   * `greatest` ignores nulls, so a first-ever send compares against
   * `mail_seen_at` alone and everything unread counts as new.
   */
  having count(*) filter (
    where r.created_at > greatest(p.mail_seen_at, n.notified_at)
  ) > 0;
$$;

-- Stamped after the send, never before -----------------------------------------
--
-- Takes the ids that were actually sent to, rather than stamping everybody the
-- query returned. A provider outage would otherwise mark a day's worth of
-- people as notified and they would hear nothing until tomorrow.
create or replace function public.mark_digested (p_ids uuid[])
returns integer
language sql
security definer
set search_path = public
as $$
  with done as (
    update public.notify_settings
       set notified_at = now()
     where profile_id = any (p_ids)
    returning 1
  )
  select count(*)::integer from done;
$$;

-- Unsubscribing, with no session ------------------------------------------------
--
-- The link at the bottom of an email is followed on whatever device the email
-- was opened on, which is frequently not the one that is signed in. Requiring a
-- session to stop email is how an unsubscribe link becomes a lie, so this takes
-- the token and nothing else.
--
-- It only ever turns things *off*. A token that leaked could be used to stop
-- somebody's email — annoying, and undone with one command — and could never be
-- used to start it, read anything, or say anything.
create or replace function public.unsubscribe (p_token uuid)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
  v_found boolean;
begin
  update public.notify_settings
     set daily = false
   where token = p_token
  returning true into v_found;

  return coalesce(v_found, false);
end;
$$;

-- Service role only. These read every address on the site between them, so
-- nothing that reaches a browser may call them.
revoke all on function public.pending_digests () from public, anon, authenticated;
revoke all on function public.mark_digested (uuid[]) from public, anon, authenticated;
revoke all on function public.unsubscribe (uuid) from public, anon, authenticated;

-- The unsubscribe page is a route, so nobody may open a room that shadows it.
-- `lib/shell/env.ts` keeps the same list and a test compares the two, so this
-- line and that map have to move together.
insert into public.reserved_slugs (slug, reason)
values ('unsubscribe', 'that is a route')
on conflict (slug) do nothing;

-- The daily-email settings go with the account, and this is why `forget` is
-- rewritten here rather than left where it was.
--
-- Erasure anonymises rather than deletes — see the migration this is copied
-- from — so `on delete cascade` never fires and a table added afterwards
-- survives it. `notify_settings` would have been left holding a preference, a
-- last-sent timestamp and an unsubscribe token belonging to somebody who asked
-- to be gone. No mail would have reached them (`pending_digests` skips banned
-- and unverified accounts, and erasure sets both), so this is not a leak of
-- messages — it is a row about a person that outlived their erasure, and the
-- privacy policy names it as something held.
--
-- Recreated in full because that is what `create or replace` requires, and the
-- only line that differs is the delete. If `forget` changes again, this is the
-- copy that is live.
create or replace function public.forget (p_name citext)
returns citext
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_id       uuid;
  v_tombname citext;
begin
  select id into v_id from public.profiles where name = p_name;
  if v_id is null then
    raise exception 'no one called %', p_name using errcode = 'no_data_found';
  end if;

  -- Short and random rather than sequential: `deleted_1` next to `deleted_2`
  -- tells you the order people left, which is information about them.
  --
  -- md5 rather than gen_random_bytes because pgcrypto lives in the `extensions`
  -- schema on a hosted project and this function pins search_path to public.
  v_tombname := 'deleted_' || substr(md5(random()::text || clock_timestamp()::text), 1, 8);

  -- Every handle they have ever held goes, including the ones in the history
  -- table. Leaving those behind would let name_changed_hands point back at a
  -- person who asked to be gone.
  delete from public.name_history where profile_id = v_id;

  -- Added with the daily email. Anything keyed on a profile has to be listed
  -- here, because the cascade this schema would otherwise rely on never runs.
  delete from public.notify_settings where profile_id = v_id;

  update public.profiles
     set name          = v_tombname,
         name_since    = now(),
         banned_at     = now(),
         banned_reason = 'account closed',
         verified_at   = null
   where id = v_id;

  -- The address is the personal datum that matters most, and it lives in
  -- auth.users rather than here. Overwritten rather than nulled: GoTrue reads
  -- these columns as non-nullable strings, and a null breaks sign-in for
  -- everybody rather than just this row.
  --
  -- On a hosted project auth.users is owned by supabase_auth_admin, which may
  -- refuse this. A half-finished erasure that reported success would be the
  -- worst outcome available, so it warns loudly and names the other route
  -- rather than failing silently or rolling the anonymisation back.
  begin
    update auth.users
       set email              = v_tombname || '@deleted.invalid',
           raw_user_meta_data = '{}'::jsonb,
           raw_app_meta_data  = '{}'::jsonb
     where id = v_id;
  exception
    when insufficient_privilege then
      raise warning 'THE ADDRESS WAS NOT ERASED: this role may not write auth.users. Delete user % through the Auth admin API to finish.', v_id;
  end;

  return v_tombname;
end;
$$;

;


-- ==========================================================================
-- 20260806020000_rooms_grew_out_of.sql
-- ==========================================================================

-- Subtopics, without a tree.
--
-- Asked for as rooms inside rooms, three to five deep. That is the change most
-- likely to produce §4.2's named failure — "40 rooms with three people each
-- kills the entire feeling" — because a subtopic room is a slice of a slice and
-- starts emptier than a top-level one. It would also rewrite every address on
-- the site: `music/12` is room-then-post, and `music/jazz/bebop/4` is not, so
-- `Location`, both directions of the URL, `go`, `leave`, `older`, the share
-- cards and the lobby all change to carry the depth.
--
-- What people actually want from nesting is available for one column. Rooms are
-- already free to make; what is missing is *relatedness* — no way to see that
-- `jazz` came out of `music`. So a room records where it was made from, and its
-- parent lists them.
--
-- Nothing else moves. No address changes, no command changes, no URL changes.
-- If real nesting is wanted later, none of this is in the way.

alter table public.rooms
  add column if not exists from_room citext
    references public.rooms (slug) on delete set null;

comment on column public.rooms.from_room is
  'the room somebody was standing in when they made this one. a label for '
  'discovery, never a permission and never part of an address.';

-- The parent asks "what grew out of me", which is a lookup by this column.
create index if not exists rooms_from_room on public.rooms (from_room)
  where from_room is not null;

-- Public, unlike `created_by`. Who opened a room is deliberately not readable
-- (§4.2 — a room has no owner and nobody should be able to build a list of
-- whose rooms are whose); where it grew out of is the opposite, because the
-- whole point is that people see it.
grant select (
  slug, gloss, ephemeral, sort_order, next_post_no, created_at,
  owner_id, archived_at, hidden_at, curated, from_room
) on public.rooms to anon, authenticated;

-- create_room, with somewhere it came from ------------------------------------
--
-- Dropped and recreated rather than replaced: `create or replace function`
-- cannot change an argument list, and adding a defaulted parameter changes it.
-- The grants go with the drop, so they are reapplied below.
drop function if exists public.create_room (citext, text);

create or replace function public.create_room (
  p_slug  citext,
  p_gloss text,
  -- Where the person was standing. Optional, and never trusted blindly — see
  -- the checks before the insert.
  p_from  citext default null
)
returns citext
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_id      uuid := auth.uid ();
  v_ok      boolean;
  v_banned  boolean;
  v_reason  text;
  v_made    integer;
  v_oldest  timestamptz;
  v_wait    integer;
  v_gloss   text := btrim(p_gloss);
  v_slug    citext := lower(btrim(p_slug::text))::citext;
  v_from    citext := nullif(lower(btrim(coalesce(p_from, '')::text)), '')::citext;
begin
  if v_id is null then
    raise exception 'you need a name before you can make a room'
      using errcode = 'insufficient_privilege';
  end if;

  -- Verified, not merely named. §4.7 lets an unverified account have one
  -- contribution so the held sentence lands; a room is not that. It is a
  -- permanent address in a shared space, and the cost of making one has to be
  -- an inbox somebody actually reads.
  select p.verified_at is not null, p.banned_at is not null
    into v_ok, v_banned
    from public.profiles p where p.id = v_id;

  -- Banned first, and said plainly. Folding it into the verified check told a
  -- banned account to go and check its email, which is a message that sends
  -- somebody looking for a link that will not help them.
  if coalesce(v_banned, false) then
    raise exception 'this account cannot post here.'
      using errcode = 'insufficient_privilege';
  end if;

  if not coalesce(v_ok, false) then
    raise exception 'check your email first — a room is permanent, so it wants a verified account. no link? type resend.'
      using errcode = 'insufficient_privilege';
  end if;

  -- Three a week. §4.2's failure is a lobby that fills faster than it empties,
  -- and the cap is what keeps one enthusiastic evening from being fifteen
  -- rooms — while leaving room for somebody who actually has three ideas.
  --
  -- A rolling window, not a calendar week. A week that resets at midnight on
  -- Sunday hands everybody three fresh rooms at the same moment, which is the
  -- one time you would least like it to.
  select count(*), min(created_at)
    into v_made, v_oldest
    from public.rooms
   where created_by = v_id
     and created_at > now() - interval '7 days';

  if v_made >= 3 then
    -- Whole days, rounded up. `justify_interval` renders
    -- "6 days 23:59:59.873763", which is a debug dump rather than an answer to
    -- "when can I make another one".
    v_wait := ceil(extract(epoch from (v_oldest + interval '7 days' - now())) / 86400);
    raise exception 'that is three rooms this week, which is the limit. you can make another %, and rooms are easier to make than to fill.',
      case when v_wait <= 1 then 'tomorrow' else 'in ' || v_wait || ' days' end
      using errcode = 'too_many_rows';
  end if;

  if v_slug ~ '^~' then
    raise exception '~ names a wall, and you already have one. pick a plain name.'
      using errcode = 'check_violation';
  end if;

  if v_slug !~ '^[a-z0-9-]{2,24}$' then
    raise exception 'a room name is 2 to 24 characters of a-z, 0-9 and -. nothing else, and no spaces.'
      using errcode = 'check_violation';
  end if;

  select reason into v_reason from public.reserved_slugs where slug = v_slug;
  if v_reason is not null then
    raise exception '% is spoken for — %.', v_slug, v_reason
      using errcode = 'check_violation';
  end if;

  if exists (select 1 from public.rooms where slug = v_slug) then
    raise exception '% already exists. try: go %', v_slug, v_slug
      using errcode = 'unique_violation';
  end if;

  -- Somebody's name is not available as a room.
  --
  -- `go marisol` and `go ~marisol` are already different addresses, so nothing
  -- breaks — but a room called `marisol` sits in the lobby under her name, with
  -- a gloss its maker chose, and §4.6's whole argument about impersonation is
  -- that it is aimed at the reader. The reader is who this protects.
  if exists (select 1 from public.profiles where name = v_slug) then
    raise exception '% is somebody''s name. try: go ~% to see them.', v_slug, v_slug
      using errcode = 'unique_violation';
  end if;

  -- §3.6 and §3.11 both rest on the gloss: the lobby reads as a building
  -- because every door says what is behind it. A room without one is a slug in
  -- a list, so it is required rather than optional, and short enough to fit the
  -- one line it gets at 380px.
  if char_length(v_gloss) < 3 or char_length(v_gloss) > 60 then
    raise exception 'say what it is for, in a few words — that is the line under the name in the lobby.'
      using errcode = 'check_violation';
  end if;

  /*
   * Where it grew out of, if anywhere.
   *
   * Checked rather than taken: the caller passes the room they were standing
   * in, and a client is not a source of truth about anything. A parent that is
   * not a real room, or is a wall, or is the room being made, is dropped and
   * the room is still made — this is a label, not a permission, and refusing to
   * create somebody's room over a bad label would be the tail wagging the dog.
   *
   * Walls are excluded because "jazz grew out of ~marisol" is not a thing
   * anybody means, and because a wall is not somewhere the lobby can send
   * people back to.
   */
  if v_from is not null
     and (v_from = v_slug
          or v_from ~ '^~'
          or not exists (select 1 from public.rooms where slug = v_from)) then
    v_from := null;
  end if;

  -- sort_order is not read for a user room: the lobby orders those by life,
  -- not by curation. Set past the curated block anyway so nothing collides if
  -- the operator ever promotes one.
  insert into public.rooms (slug, gloss, ephemeral, sort_order, created_by, from_room)
  values (v_slug, v_gloss, false, 500, v_id, v_from);

  return v_slug;
end;
$$;

revoke all on function public.create_room (citext, text, citext) from public, anon;
grant execute on function public.create_room (citext, text, citext) to authenticated;

-- What grew out of a room -------------------------------------------------------
--
-- Hidden rooms are excluded, because §6's lever has to reach every surface that
-- names a room. Quiet ones are not: the lobby drops a room after a fortnight of
-- silence and this listing is exactly the way back to one, which is the point
-- of it existing at all.
create or replace function public.rooms_from (p_slug citext)
returns table (slug citext, gloss text)
language sql
stable
security definer
set search_path = public
as $$
  select r.slug, r.gloss
    from public.rooms r
   where r.from_room = p_slug
     and r.hidden_at is null
   order by r.created_at;
$$;

grant execute on function public.rooms_from (citext) to anon, authenticated;

;


-- ==========================================================================
-- 20260808000000_notify_on_by_default.sql
-- ==========================================================================

-- The daily email is on unless you turn it off.
--
-- The previous migration argued the other way and named the reason: §4.1 leans
-- "pull-only, no push, no email", and consent was how both halves of that were
-- kept. What that argument missed is the sentence directly above it in the same
-- section — notifications are the *highest-priority unsolved item*, because "no
-- notification means no reason to return".
--
-- An opt-in notification does not solve that, and cannot. The people who type
-- `notify on` are the people already coming back; they are the ones who least
-- need reminding. Everybody else — the person who said one thing, got a good
-- answer three days later, and never found out — is exactly who the feature is
-- for, and an opt-in never reaches them. A default is not a detail here. It is
-- the whole of whether the feature does its job.
--
-- WHAT THIS IS NOT
--
-- It is not permission to email anybody. Every guard the opt-in version had is
-- still here, and they are the reason defaulting on is defensible rather than
-- rude:
--
--   * `pending_digests` still requires `verified_at is not null`, so nothing is
--     sent to an address until somebody has followed a key that arrived in it.
--     A stranger whose address was typed into a signup box gets one key and
--     never hears from this site again. That is the guard that matters most and
--     it is untouched.
--   * Still at most one a day, and only on a day somebody actually answered
--     you. A quiet week is a silent week.
--   * Still stopped by `notify off`, by the link at the bottom of every one, and
--     by the one-click header mail clients read without opening anything.
--   * Still nothing else, ever. There is no second kind of email to be enrolled
--     into later.
--
-- HOW OFF STAYS OFF
--
-- The one thing a default flip must never do is re-enable somebody who turned
-- it off. It cannot here, and not by being careful: `set_notify(false)` writes a
-- row with `daily = false` rather than deleting one, and `unsubscribe` does the
-- same. So "off" is a stored fact, and "never touched it" is the absence of a
-- row. Only the second becomes on.
--
-- Every profile gets a row from now on, made by a trigger rather than by the
-- signup route, because a route is a thing somebody can add a second copy of
-- and a trigger is not. Existing profiles are backfilled below.

alter table public.notify_settings
  alter column daily set default true;

comment on column public.notify_settings.daily is
  'On by default. False only because somebody said so — notify off, or the link '
  'in an email. The absence of a row is not "off"; see the trigger below.';

-- A row for everybody, from the moment there is somebody --------------------
--
-- On `profiles` rather than `auth.users`: a profile is what this site means by
-- a person, it is what `notify_settings` references, and `auth.users` is a
-- schema owned by somebody else that this project should not be hanging
-- triggers off.
create or replace function public.notify_default ()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  -- `on conflict do nothing` rather than an upsert. If a row somehow exists
  -- already, it holds a decision, and a decision beats a default.
  insert into public.notify_settings (profile_id)
  values (new.id)
  on conflict (profile_id) do nothing;
  return new;
end;
$$;

drop trigger if exists profiles_notify_default on public.profiles;
create trigger profiles_notify_default
  after insert on public.profiles
  for each row execute function public.notify_default ();

-- The backfill ---------------------------------------------------------------
--
-- Everybody who already had an account and never touched the setting. They have
-- no row, so this gives them one, on.
--
-- This is the only genuinely awkward statement in the file, and it is worth
-- being plain about why: these people signed up while the privacy policy said
-- the summary was "off unless you type notify on". That promise is being
-- changed under them. It is defensible — the mail is about replies to their own
-- posts, it is capped at one a day, and it carries a one-click stop — and it is
-- still a change to something they were told.
--
-- If that trade is ever the wrong one (a project with real people on it, rather
-- than one that has not launched), delete this statement and keep the rest. New
-- accounts are then on by default and existing ones are untouched, which is the
-- conservative version of the same change.
insert into public.notify_settings (profile_id, daily)
select p.id, true
  from public.profiles p
 where not exists (
   select 1 from public.notify_settings n where n.profile_id = p.id
 )
   -- Not the erased. `forget` deletes their row on purpose, and re-creating one
   -- here would undo an erasure with a backfill — the exact shape of bug that
   -- migration was written to prevent.
   and p.banned_at is null
on conflict (profile_id) do nothing;

-- Reading your own setting ----------------------------------------------------
--
-- The fallback flips with the default. It should be unreachable now that every
-- profile has a row, and it is written correctly anyway: a `coalesce` that
-- still said `false` would be a second, quieter answer to the same question,
-- and the two would disagree for exactly the accounts nothing else covers.
create or replace function public.notify_state ()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(
    (select daily from public.notify_settings where profile_id = auth.uid ()),
    true
  );
$$;

revoke all on function public.notify_state () from public, anon;
grant execute on function public.notify_state () to authenticated;

-- Turning it on, when it is already on ----------------------------------------
--
-- Unchanged in behaviour and recreated for one line of comment, because the
-- verified check now reads oddly and the reason it stays matters.
--
-- `set_notify(true)` still refuses an unverified account. That looks redundant
-- when the default is on — but the default is a row in a table, and the thing
-- that actually decides whether mail is sent is `pending_digests`, which
-- requires `verified_at`. Somebody unverified is therefore "on" and receiving
-- nothing, which is the correct state and a confusing one to be told about. The
-- refusal is how they find out, in a sentence that names the fix.
create or replace function public.set_notify (p_on boolean)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
  v_verified timestamptz;
begin
  if auth.uid () is null then
    raise exception 'you have to be signed in for that.';
  end if;

  select verified_at into v_verified from public.profiles where id = auth.uid ();

  if p_on and v_verified is null then
    raise exception 'follow the link in your email first — then i can send you things.';
  end if;

  insert into public.notify_settings (profile_id, daily)
  values (auth.uid (), p_on)
  on conflict (profile_id) do update set daily = excluded.daily;

  return p_on;
end;
$$;

revoke all on function public.set_notify (boolean) from public, anon;
grant execute on function public.set_notify (boolean) to authenticated;

;


-- ==========================================================================
-- 20260809000000_no_mail_to_nowhere.sql
-- ==========================================================================

-- No mail to an address that cannot receive it.
--
-- Found while working out what a public repository changes about this project,
-- and it turned out to be a live defect rather than a disclosure: the five
-- accounts `seed.sql` creates live at `@seed.invalid`, a TLD the standards
-- reserve so that it can never resolve. They are verified, their posts are in
-- the lobby, and the daily email is on by default — so the first time a real
-- person answers jameson, the digest job tries `jameson@seed.invalid`, and
-- tries again every day there is something new.
--
-- Every one of those is a hard bounce. Hard bounces are what gets a sending
-- domain throttled or cut off, and they cost most on a domain that has just
-- been warmed, which is the state this one is in. The failure is not that the
-- seed accounts miss their email — it is that everybody else stops getting
-- sign-in keys.
--
-- The public repository is what made the second half of it reachable on
-- purpose: the seeded names are printed on the site and written down in a
-- readable repo, so `login jameson` is something anyone can type, and each
-- attempt is another bounce. That route is guarded in
-- lib/auth/deliverable.ts; this file guards the one nobody is watching.

create or replace function public.pending_digests ()
returns table (
  profile_id uuid,
  name       citext,
  email      text,
  unread     integer,
  token      uuid
)
language sql
stable
security definer
set search_path = public
as $$
  select p.id,
         p.name,
         u.email::text,
         count(r.*)::integer,
         n.token
    from public.notify_settings n
    join public.profiles p on p.id = n.profile_id
    join auth.users u on u.id = p.id
    join public.posts po on po.author_id = p.id
    join public.rooms rm on rm.slug = po.room_slug
    join public.replies r on r.post_id = po.id
   where n.daily
     and p.banned_at is null
     and p.verified_at is not null
     and u.email is not null
     /*
      * Never to an address that provably cannot receive.
      *
      * RFC 2606 and RFC 6761 reserve these so they can never resolve, which is
      * exactly why `seed.sql` uses `@seed.invalid` for its five accounts. Those
      * accounts are verified, their posts sit in the lobby, and the digest is
      * on by default — so the first time a real person answers jameson, this
      * query hands the job `jameson@seed.invalid` and keeps doing it every day
      * there is something new. Every one is a hard bounce against a sending
      * domain that has only just been warmed, and a steady trickle of those is
      * a suspended account and no sign-in keys for anybody.
      *
      * Here as well as in lib/auth/deliverable.ts, because the two decide
      * different sends: that one guards a route somebody types at, this one
      * guards a cron job nobody is watching.
      */
     and u.email !~* '(@|\.)(example\.com|example\.net|example\.org)$'
     and u.email !~* '\.(test|example|invalid|localhost)$'
     and (n.notified_at is null or n.notified_at < now() - interval '20 hours')
     -- The same three the badge uses: a reply under a hidden post, or in a
     -- closed room, is a notification pointing at nothing.
     and r.hidden_at is null
     and po.hidden_at is null
     and rm.hidden_at is null
     and r.author_id <> p.id
     and r.created_at > p.mail_seen_at
   group by p.id, p.name, u.email, n.token, n.notified_at
  /*
   * Two different questions, and the first version answered only one.
   *
   * `unread` is everything waiting, so the number in the email is the number in
   * the badge. Whether to send at all is a different question: has anything
   * arrived *since the last email*. Gating on unread alone meant somebody who
   * got a digest and never read their mail was sent the identical email every
   * day for as long as the pile sat there — which is precisely the daily nag
   * this feature is written to not be, and it contradicted the sentence the
   * command itself prints.
   *
   * `greatest` ignores nulls, so a first-ever send compares against
   * `mail_seen_at` alone and everything unread counts as new.
   */
  having count(*) filter (
    where r.created_at > greatest(p.mail_seen_at, n.notified_at)
  ) > 0;
$$;

-- Belt as well as braces: the seeded accounts are switched off explicitly.
--
-- The filter above is the rule and this is not a second copy of it — it is a
-- statement about these five in particular, who did not ask for email and could
-- not read it if they got it. `notify_default` gives every new profile a row
-- saying on, and the seed makes profiles, so without this they are enrolled
-- like everybody else and only the query above stands between them and a send.
update public.notify_settings n
   set daily = false
  from auth.users u
 where u.id = n.profile_id
   and u.email like '%@seed.invalid';

;


-- ==========================================================================
-- 20260810000000_lobby_uses_its_index.sql
-- ==========================================================================

-- The lobby stops reading every post on the site to draw itself.
--
-- Asked what happens to the lobby at hundreds of rooms. Built one with 310 and
-- measured: **1112 ms**, on every page load, to show twelve rooms.
--
-- The cause is one `or`. `room_overview` finds each room's newest post with a
-- lateral join, and when `feed` was added — a room that holds nothing itself and
-- whose lobby line has to come from everybody's walls — the two cases were
-- folded into a single predicate:
--
--   where ( (r.slug = 'feed' and pr.owner_id is not null and ...)
--           or (r.slug <> 'feed' and p.room_slug = r.slug) )
--
-- `p.room_slug = r.slug` is exactly what `posts_room_recent (room_slug,
-- created_at desc)` is for. Sitting inside an `or`, it stops being usable:
-- Postgres cannot know which branch applies until it has the row, so it
-- sequentially scans **every post on the site, once per room**. The plan says
-- so plainly — `Seq Scan on posts ... loops=310`, `Rows Removed by Join Filter:
-- 320`. That is rooms × posts, and it grows with the product of the two.
--
-- Nothing was wrong with the *answer*. It has always been right, and it was
-- fast at nine rooms, which is why nothing caught it: the cost is invisible
-- until the site works.
--
-- Split into two laterals, each guarded on the outer row, so the ordinary path
-- gets its index back and the feed path runs for the one row it is about.
-- Same query, measured again on the same 310 rooms: **5.9 ms**.

create or replace view public.room_overview
with (security_invoker = true) as
select
  r.slug,
  r.gloss,
  r.ephemeral,
  r.sort_order,
  -- One of the two is always null: the guards are mutually exclusive, so
  -- coalesce is a choice between them rather than a fallback.
  coalesce(own.body, feed.body)             as latest_body,
  coalesce(own.created_at, feed.created_at) as latest_at,
  coalesce(own_author.name, feed_author.name) as latest_author,
  r.curated
from public.rooms r

-- An ordinary room: its own newest post.
--
-- `r.slug <> 'feed'` sits *inside* the subquery rather than in a join
-- condition. In the ON clause the lateral would still be executed and then
-- discarded; here it is a one-time filter on the outer row, and
-- `p.room_slug = r.slug` is left alone as the only predicate the index has to
-- serve.
left join lateral (
  select p.body, p.created_at, p.author_id
    from public.posts p
   where r.slug <> 'feed'
     and p.room_slug = r.slug
     and p.hidden_at is null
     and public.is_visible (p.room_slug, p.created_at)
   order by p.created_at desc
   limit 1
) own on true

-- The feed: the newest thing on anybody's wall.
--
-- Same filters `wall_feed` uses, or the lobby advertises a post the feed itself
-- will not show. Runs for one row of the whole query.
left join lateral (
  select p.body, p.created_at, p.author_id
    from public.posts p
    join public.rooms pr on pr.slug = p.room_slug
   where r.slug = 'feed'
     and pr.owner_id is not null
     and pr.hidden_at is null
     and pr.archived_at is null
     and p.hidden_at is null
     and public.is_visible (p.room_slug, p.created_at)
   order by p.created_at desc
   limit 1
) feed on true

left join public.profiles own_author on own_author.id = own.author_id
left join public.profiles feed_author on feed_author.id = feed.author_id
where r.hidden_at is null
  and r.archived_at is null
  and r.owner_id is null
  and (
    r.curated
    or coalesce(own.created_at, r.created_at) > now() - interval '14 days'
  );

comment on view public.room_overview is
  'The lobby (§3.11). One row per listable room with its newest post. Two '
  'laterals rather than one predicate with an or in it — the or made this '
  'rooms x posts, see the migration.';

-- An index the fade in the WHERE clause can use once there are enough rooms for
-- the sequential scan over `rooms` to matter. Cheap, and the query already
-- filters on exactly these three.
create index if not exists rooms_listable
  on public.rooms (curated, sort_order)
  where hidden_at is null and archived_at is null and owner_id is null;

;


-- ==========================================================================
-- 20260811000000_reply_to_a_reply.sql
-- ==========================================================================

-- Answering a reply, without a tree.
--
-- Asked for directly: "I want to be able to reply to replies." Until now a post
-- had a flat list of answers and there was no way to point at one of them, so a
-- thread with six replies in it was six people talking past each other.
--
-- §4.3 decided replies get no address of their own, and this changes that half
-- on purpose — you cannot answer a thing you cannot name. What it does *not*
-- change is the other half of that decision, which was really about nesting:
--
--   * A reply is numbered **within its post**, not globally. `music/12` has
--     replies 1, 2, 3, and the address of the conversation is still `music/12`.
--     Nothing gains a segment, nothing new appears in a URL, and `go` learns no
--     new shape.
--   * `to_reply_no` is a *pointer*, not a parent in a tree. The list stays flat
--     and in time order, and an answer to an answer says which one it is
--     answering. Same choice as rooms that grew out of a room, for the same
--     reason: a tree on a 380px screen is unreadable by the fourth level, and
--     the thing people actually want is to know what somebody is responding to.
--
-- So a thread reads:
--
--   1  marisol, 2h ago
--      warped ones still play, they just wobble
--   2  tuck, 1h ago  → 1
--      that is what makes them worth keeping
--
-- rather than drifting right until the words are two characters wide.

-- The address, and the pointer ------------------------------------------------
alter table public.replies
  add column if not exists reply_no    integer,
  add column if not exists to_reply_no integer;

comment on column public.replies.reply_no is
  'The reply''s number within its post. Permanent and never reused, like a '
  'post''s number within its room (§3.4).';
comment on column public.replies.to_reply_no is
  'Which reply this answers, if it answers one rather than the post. A label '
  'for reading, never a parent in a tree — the listing stays flat.';

-- Backfill, in the order they were written, which is the order they have always
-- been read in.
with numbered as (
  select id, row_number() over (partition by post_id order by created_at, id) as n
    from public.replies
)
update public.replies r
   set reply_no = numbered.n
  from numbered
 where numbered.id = r.id
   and r.reply_no is null;

alter table public.replies alter column reply_no set not null;

-- Never reused, exactly like a post's number in a room.
create unique index if not exists replies_address on public.replies (post_id, reply_no);

-- The allocator ---------------------------------------------------------------
--
-- On `posts`, mirroring `rooms.next_post_no`. Kept on the row rather than
-- derived from `max(reply_no) + 1`, for the reason §3.4 already gives: a hidden
-- reply leaves a gap, and `max` cannot see it, so deriving would hand the next
-- person an address somebody else already had.
alter table public.posts
  add column if not exists next_reply_no integer not null default 1;

update public.posts p
   set next_reply_no = coalesce(
     (select max(r.reply_no) + 1 from public.replies r where r.post_id = p.id),
     1
   );

-- Allocating one --------------------------------------------------------------
--
-- A trigger on the table rather than a line inside `create_reply`, and that is
-- the second attempt. The first put the allocation in the function, which meant
-- every *other* writer — `seed.sql`, and fifteen inserts in the schema tests —
-- had to compute a number itself or fall foul of the not-null. Fifteen places
-- that each have to remember an invariant is fifteen places that can forget it.
--
-- Here, an address is a property of the table: anything that inserts a reply
-- gets a correct one, in insert order, without knowing that reply numbers
-- exist. An explicit `reply_no` is still honoured, which is what lets a data
-- move carry the original addresses across.
create or replace function public.allocate_reply_no ()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.reply_no is null then
    -- Read and bump in one statement, so two people answering at the same
    -- moment cannot be handed the same number (§3.4).
    update public.posts
       set next_reply_no = next_reply_no + 1
     where id = new.post_id
    returning next_reply_no - 1 into new.reply_no;
  end if;
  return new;
end;
$$;

drop trigger if exists replies_allocate_no on public.replies;
create trigger replies_allocate_no
  before insert on public.replies
  for each row execute function public.allocate_reply_no ();

-- Writing one ------------------------------------------------------------------
--
-- Replies used to be inserted straight from the browser under a policy. That
-- cannot allocate a number: two people answering at the same moment would read
-- the same `next_reply_no` and write the same address. So this moves behind a
-- `security definer` function, exactly as posts did, and the insert grant goes.
--
-- Everything the policy checked is checked here and in the same order, so no
-- refusal changes wording: signed in, allowed to contribute (§4.7), and the post
-- readable — which is what stops a reply landing on a hidden post or in a
-- closed room.
create or replace function public.create_reply (
  p_room     citext,
  p_post_no  integer,
  p_body     text,
  -- Which reply is being answered. Null means the post itself, which is what
  -- `reply` with no number has always meant.
  p_to_reply integer default null
)
returns integer
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_id      uuid := auth.uid ();
  v_post_id bigint;
  v_no      integer;
begin
  if v_id is null then
    raise exception 'you have to be signed in to say something.'
      using errcode = 'insufficient_privilege';
  end if;

  if not public.may_contribute (v_id) then
    raise exception 'check your email to keep saying things.'
      using errcode = 'insufficient_privilege';
  end if;

  select id into v_post_id
    from public.posts
   where room_slug = p_room and post_no = p_post_no;

  if v_post_id is null or not public.post_is_readable (v_post_id) then
    raise exception 'that post is not here.' using errcode = 'no_data_found';
  end if;

  /*
   * A pointer at something that is not there is worse than no pointer: it
   * renders as `→ 4` next to a thread that has three replies. Dropped rather
   * than refused, on the same reasoning as a room's `from_room` — losing
   * somebody's sentence over a label they mistyped is the worse trade.
   */
  if p_to_reply is not null
     and not exists (
       select 1 from public.replies
        where post_id = v_post_id and reply_no = p_to_reply and hidden_at is null
     ) then
    p_to_reply := null;
  end if;

  -- The number comes from the trigger above, so this does not repeat it — the
  -- one place that knows how an address is allocated is the table.
  insert into public.replies (post_id, author_id, body, to_reply_no)
  values (v_post_id, v_id, p_body, p_to_reply)
  returning reply_no into v_no;

  return v_no;
end;
$$;

revoke all on function public.create_reply (citext, integer, text, integer)
  from public, anon;
grant execute on function public.create_reply (citext, integer, text, integer)
  to authenticated;

-- The browser no longer writes this table directly. The policy stays: it is
-- what `post_is_readable` is enforced by for anything that still can.
revoke insert on public.replies from authenticated;

-- Reading the two new columns.
--
-- `grant select on public.replies` is table-wide and always has been, so these
-- are already readable and this line changes nothing. It is here to be explicit
-- about the decision rather than to make it: both are on the screen — a reply's
-- number and which reply it answers are exactly what the thread prints — so
-- publishing them is what is wanted. The rule is the one `profiles` has: a
-- column on a table with a table-wide select grant is public the moment it
-- exists, so ask whether you would publish it before adding it.
grant select (reply_no, to_reply_no) on public.replies to anon, authenticated;

;


-- ==========================================================================
-- 20260812000000_four_thousand.sql
-- ==========================================================================

-- Four thousand characters, and room for more than one paragraph.
--
-- The cap was 2000, and length was never actually the thing stopping a longer
-- piece of writing: the prompt is a single-line `<input>`, so a body could be
-- two thousand characters and had to be one unbroken block. `write` fixes that
-- half; this is the other.
--
-- 4000 rather than "no limit". A limit has to exist — `body` is a `text` column
-- with no ceiling of its own, and the one thing worse than a cap is a room
-- listing that has to load somebody's novel to draw a one-line preview. Four
-- thousand is roughly eight hundred words, which is a long blog post and a very
-- long thing to read on a phone, and it is where the honest ceiling sits.
--
-- The check is on `char_length`, which counts characters rather than bytes, so
-- the limit means the same thing in every language. That was already true and
-- is worth not breaking.

alter table public.posts drop constraint posts_body_length;
alter table public.posts add constraint posts_body_length
  check (char_length(body) between 1 and 4000);

-- Replies get the same ceiling, and that is deliberate rather than tidy. A
-- reply is a contribution like any other — §4.3 makes it addressable now, and
-- the case that argues for four thousand characters in a post (somebody
-- explaining something properly) argues at least as hard for four thousand in
-- the answer to it.
alter table public.replies drop constraint replies_body_length;
alter table public.replies add constraint replies_body_length
  check (char_length(body) between 1 and 4000);

comment on constraint posts_body_length on public.posts is
  'Between 1 and 4000 characters. Stated in three other places — the client '
  'maxLength, friendly() and /about — and lib/data/writer.test.ts reads this '
  'file to check they still agree.';

;


-- ==========================================================================
-- 20260812010000_hello_is_a_route.sql
-- ==========================================================================

-- /hello is the landing page now, so nobody may take it as a room name.
--
-- In its own migration rather than added to the insert that created the table:
-- that one may already be applied, and a row added to an applied file never
-- runs. This is the rule `CHANGING-IT.md` states for adding a route, followed.
--
-- A room called `hello` would be shadowed by the page forever — `go hello`
-- would work, thewall.social/hello would not be the room, and §3.4's "the
-- prompt path is the URL" would be quietly false for exactly one room.
insert into public.reserved_slugs (slug, reason)
values ('hello', 'that is a route')
on conflict (slug) do nothing;

;


-- ==========================================================================
-- 20260812020000_grants_are_a_denylist.sql
-- ==========================================================================

-- Two holes, one root: every grant so far has been written as though the
-- database started with none.
--
-- A Supabase project runs `alter default privileges in schema public grant all
-- on tables to anon, authenticated` before any of this ever executes. So each
-- `create table` here is born with INSERT, UPDATE, DELETE, TRUNCATE,
-- REFERENCES and TRIGGER already granted to the two roles the browser can
-- assume, and the careful `grant select on ...` lines added nothing — they
-- restated a privilege the table already had.
--
-- None of that showed up in the test suite, because the suite runs on plain
-- Postgres, where a new table has no grants at all. Every assertion about
-- grants passed by measuring a database shaped differently from the one this
-- ships to. `supabase/tests/_shim.sql` now sets the same default privileges,
-- which is what turned this up.
--
-- What was actually reachable:
--
--   * `truncate public.posts cascade` as **anon**. Row-level security does not
--     apply to TRUNCATE — there is no row to filter — so the policies that hold
--     every other write are simply not consulted. Verified: 21 posts before,
--     0 after, from a role holding nothing but the publishable key. It is not
--     reachable through PostgREST today, which speaks SELECT/INSERT/UPDATE/
--     DELETE and no more, but "the API happens not to expose the verb" is not a
--     control, and it costs nothing to stop relying on it.
--
--   * INSERT, UPDATE and DELETE for **anon** on posts, profiles, replies,
--     rooms, reserved_slugs and name_history. Those *are* reachable, and they
--     held — but they held on RLS alone, with the grant layer contributing
--     nothing. `20260804000000` and `20260805050000` both exist because one
--     layer holding by itself is how the last two bypasses happened.
--
--   * `require_can_contribute(uuid)` callable by any signed-in account, though
--     its migration says `revoke ... from public, anon` — the revoke named the
--     one role the default privileges had not granted to.
--
-- The fix inverts the posture. Privileges for anon and authenticated are taken
-- away wholesale and then handed back by name, and the default privileges are
-- turned off so the next `create table` starts empty. From here a migration
-- that forgets to grant produces a visibly broken feature; before, one that
-- forgot to revoke produced a silently open table.

-- Everything, gone -------------------------------------------------------------
--
-- **This takes the column-scoped grants with it.** `revoke all on <table>`
-- removes that grantee's column privileges as well as the table-level ones,
-- which is not what the wording suggests and is worth stating because getting
-- it wrong here does not look like a permissions bug: `rooms` becomes
-- unreadable, and the first symptom is that reading a *post* fails, because the
-- policy on `posts` calls `is_visible()`, which reads `rooms` as the caller.
-- Nothing anywhere says the word "rooms". The column list is restored below.

revoke all on all tables in schema public from anon, authenticated;
revoke all on all sequences in schema public from anon, authenticated;
revoke all on all functions in schema public from anon, authenticated;

-- And no new object arrives armed. Anything created in `public` after this
-- lands with nothing granted to the two browser roles.
--
-- This matches the role that runs the migration, which is `postgres` both for
-- `scripts/db-deploy.sh` and for the SQL editor. A project whose migrations
-- were applied as some other role keeps that role's defaults, so the
-- assertions in `supabase/tests/schema.test.sql` check the resulting grants
-- rather than the default-privilege rows themselves.
alter default privileges in schema public revoke all on tables from anon, authenticated;
alter default privileges in schema public revoke all on sequences from anon, authenticated;
alter default privileges in schema public revoke all on functions from anon, authenticated;

-- Reading, handed back ---------------------------------------------------------
--
-- §3.9: reading is anonymous and asks for nothing, so both roles read the same
-- five relations. `rooms` is deliberately absent — the lobby reads
-- `room_overview`, and the columns anon may see on the table itself are granted
-- one by one in `20260805000000_user_rooms.sql`.

grant select on public.posts, public.replies, public.profiles,
                public.reserved_slugs, public.room_overview
  to anon, authenticated;

-- `rooms` by the column, restoring what the revoke above took. The list is the
-- one from `20260806020000_rooms_grew_out_of.sql` and the omission is the
-- point: `created_by` is not in it, so who opened a room stays unreadable
-- (§4.2 — a room has no owner, and that has to be true of the data, not only of
-- the interface). The assertion in `supabase/tests/schema.test.sql` names
-- `created_by` directly, so a future column added to this list by habit is
-- caught rather than inherited.
grant select (
  slug, gloss, ephemeral, sort_order, next_post_no, created_at,
  owner_id, archived_at, hidden_at, curated, from_room
) on public.rooms to anon, authenticated;

-- And the two columns `replies` gained after its table-level grant was written.
-- Covered by the table grant above; restated so that removing the table grant
-- one day does not silently un-address every reply.
grant select (reply_no, to_reply_no) on public.replies to anon, authenticated;

-- Writing, handed back ---------------------------------------------------------
--
-- Nine functions, and no table. Every write in this product goes through a
-- `security definer` function that decides for itself whether the caller has
-- earned it; the tables take no writes from a browser at all. The list is
-- closed on purpose — a tenth function is a line in this file, which is the
-- point of writing it out rather than looping over `pg_proc`.

grant execute on function public.change_name (citext) to authenticated;
grant execute on function public.create_post (citext, text) to authenticated;
grant execute on function public.create_reply (citext, integer, text, integer) to authenticated;
grant execute on function public.create_room (citext, text, citext) to authenticated;
grant execute on function public.mail () to authenticated;
grant execute on function public.mail_count () to authenticated;
grant execute on function public.mark_mail_seen () to authenticated;
grant execute on function public.notify_state () to authenticated;
grant execute on function public.set_notify (boolean) to authenticated;

-- Verification is not something you may award yourself ---------------------------
--
-- `mark_verified()` took no arguments, marked `auth.uid()`, and was granted to
-- `authenticated`. Every one of those is defensible on its own and together
-- they hand out the §4.7 gate for free:
--
--   await supabase.rpc('mark_verified')
--
-- from the console of anyone signed in. And everybody is signed in from the
-- moment they pick a name — that is the whole of §3.9, and `/api/signup`
-- creates the account with `email_confirm: true` so the session can start
-- before the inbox is ever opened. So the one control standing between "typed
-- an address" and "may post without limit" was a function the browser was
-- allowed to call and that asked for no proof.
--
-- `20260804000000` moved this behind an RPC to close a table-wide UPDATE grant,
-- and its comment says "auth.uid() means a caller can only ever mark
-- themselves". That is true and it is the wrong question. The gate is not about
-- *which* row gets marked; it is about whether anybody read the email.
--
-- Now the caller says who, and only the service role may call it. That role
-- exists only on the server, and the two places that use it — `/auth/callback`
-- and `/api/login/code` — have both just watched a token minted for that
-- address be spent, which is the claim §4.7 actually wants.

drop function if exists public.mark_verified ();

create or replace function public.mark_verified (p_user uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if p_user is null then
    raise exception 'mark_verified needs a user' using errcode = 'null_value_not_allowed';
  end if;

  update public.profiles
     set verified_at = now()
   where id = p_user
     and verified_at is null;
end;
$$;

revoke all on function public.mark_verified (uuid) from public, anon, authenticated;
grant execute on function public.mark_verified (uuid) to service_role;

;


-- ==========================================================================
-- seed.sql — §5, the rooms arrive warm
-- ==========================================================================

-- Cold start (§5).
--
-- "An empty room is worse than no room. The demo cannot launch to a ghost
-- town." So the rooms arrive warm, and what is written here follows §5 to the
-- letter: content that reads like ordinary people — a broken AC, a bad beat, a
-- dad's records in the garage, four pounds of tomatoes — and explicitly NOT dev
-- in-jokes, which §5 names as the first draft's failure and the thing that
-- narrows the audience to people who already like terminals.

-- Seed accounts, so the seeded posts have real authors. There is no password
-- and the addresses are .invalid, so nobody can sign in as them.
--
-- If this statement is REFUSED on a hosted project ("permission denied for
-- table users"), that is the auth schema being owned by supabase_auth_admin
-- rather than by the role in your connection string. It is the one step here
-- that a hosted project can reject, and it stops the whole seed, which leaves
-- you with a schema and no rooms.
--
-- The fix is to create the five accounts through the Auth admin API instead
-- and then re-run the seed. The API assigns its own ids, so the literal UUIDs
-- below would need to become lookups by email — ask for that change rather
-- than hand-editing, since the ids are referenced from four places.
--
-- The local path (`supabase start`) is not affected: the CLI seeds as an owner.
--
-- The empty strings are not decoration. Auth reads these token columns into
-- plain strings, and a NULL makes it fail with "converting NULL to string is
-- unsupported" on any query that touches the row — which means hand-seeded
-- users can break sign-in for everybody, not just themselves. Writing '' is
-- what the admin API would have done.
insert into auth.users (
  id, instance_id, aud, role, email,
  encrypted_password, email_confirmed_at,
  confirmation_token, recovery_token, email_change, email_change_token_new,
  raw_app_meta_data, raw_user_meta_data,
  created_at, updated_at
)
select
  id, '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', email,
  '', now(),
  '', '', '', '',
  '{"provider":"email","providers":["email"]}'::jsonb, '{}'::jsonb,
  now(), now()
from (values
  ('11111111-1111-4111-8111-111111111111'::uuid, 'jameson@seed.invalid'),
  ('22222222-2222-4222-8222-222222222222'::uuid, 'marisol@seed.invalid'),
  ('33333333-3333-4333-8333-333333333333'::uuid, 'tuck@seed.invalid'),
  ('44444444-4444-4444-8444-444444444444'::uuid, 'ren@seed.invalid'),
  ('55555555-5555-4555-8555-555555555555'::uuid, 'dev@seed.invalid')
) as seed (id, email)
on conflict (id) do nothing;

-- verified_at is set because these are not people with inboxes. Left null they
-- would each be one contribution away from being asked to check an address
-- that does not exist (§4.7, as revised).
insert into public.profiles (id, name, verified_at) values
  ('11111111-1111-4111-8111-111111111111', 'jameson', now()),
  ('22222222-2222-4222-8222-222222222222', 'marisol', now()),
  ('33333333-3333-4333-8333-333333333333', 'tuck',    now()),
  ('44444444-4444-4444-8444-444444444444', 'ren',     now()),
  ('55555555-5555-4555-8555-555555555555', 'dev',     now())
on conflict (id) do nothing;

-- §4.2 — a fixed, curated set at launch. Room creation stays closed and the
-- decay rules stay written-but-unenabled, because 40 rooms with three people
-- each kills the entire feeling and the room list is the first impression.
insert into public.rooms (slug, gloss, ephemeral, sort_order) values
  ('commons',   'everything, briefly',        true,  0),
  ('music',     'what you are listening to',  false, 1),
  ('builders',  'what you are making',        false, 2),
  -- builders was added after launch. §4.2 leans "fixed set at launch" and the number was
  -- never the point — 40 rooms with three people each is. A handful with
  -- something recent in all of them is still a building rather than a
  -- directory, and this is the room the earliest people here are most likely
  -- to have something to put in.
  ('poker',     'bad beats and good folds',   false, 3),
  ('kitchen',   'what you cooked',            false, 4),
  -- §5 — one room should be a mood, not a topic. Mood rooms are what make this
  -- feel like a place rather than a forum.
  ('latenight', 'quiet hours only',           false, 5),
  -- §5 again: a room is an invitation to tell somebody something, not a
  -- category. "what you are holding" gets a story where "cryptocurrency" gets
  -- a subject line.
  ('crypto',    'what you are holding',       false, 6),
  ('movies',    'what you watched',           false, 7),
  -- The room about the site itself. There is no support address on the page and
  -- no form; a bug nobody can report is a bug that gets left.
  ('feedback',  'what is broken, and what should be here', false, 8)
on conflict (slug) do nothing;

-- feed is inserted by its own migration, not here: it holds no posts of its own
-- and exists on every project whether or not this seed was ever run.

-- Curated, always: these are the furniture. The column defaults to false, which
-- is right for a room somebody makes and wrong for every room in this file — a
-- seeded room that was not marked would fade out of the lobby after a fortnight
-- of quiet, which is the one thing curated rooms must never do.
update public.rooms set curated = true where owner_id is null and created_by is null;

-- Ordering is set rather than left to the insert, because `on conflict do
-- nothing` skips a room that already exists — so on a project seeded before
-- builders was written, it would arrive with its sort_order and everything
-- after it would keep the old one, leaving two rooms tied and the lobby order
-- undefined.
update public.rooms set sort_order = v.sort_order
  from (values ('commons', 0), ('music', 1), ('builders', 2),
               ('poker', 3), ('kitchen', 4), ('latenight', 5),
               ('crypto', 6), ('movies', 7), ('feedback', 8), ('feed', 9))
       as v (slug, sort_order)
 where rooms.slug = v.slug::citext;

-- One wall, so the feature is discoverable rather than invisible.
--
-- A wall is a room with an owner and it is created lazily, on the first thing
-- somebody puts on it — which means a fresh project has none at all, and the
-- first visitor to a profile learns nothing about walls existing. §5's argument
-- against a ghost town applies here exactly as it does to the rooms.
--
-- It is deliberately not in the lobby, and gets that for free: `room_overview`
-- filters `owner_id is null`. sort_order is set high for the same reason it is
-- set at all — it is never read for a wall, and a number that collides with a
-- real room would be a trap for whoever adds the seventh one.
insert into public.rooms (slug, gloss, ephemeral, sort_order, owner_id) values
  ('~marisol', 'what marisol is saying', false, 1000,
   '22222222-2222-4222-8222-222222222222')
on conflict (slug) do nothing;

-- Posts are inserted directly here rather than through create_post(), because
