-- The column types come from the VALUES list, which is all text, so each one is
-- cast explicitly on the way in.
-- Unlike the inserts above, replies have no natural key to conflict on, so
-- re-running the seed would quietly double them. The guard makes the whole
-- file safe to run more than once, which matters because running it is the
-- step people repeat while working out why a project looks empty.
--
-- No `reply_no` here. A reply is addressable now — `reply 2 <something>` answers
-- reply 2 — but the number is allocated by a trigger on the table, so nothing
-- that writes a reply has to know that reply numbers exist.
insert into public.replies (post_id, author_id, body, created_at)
select p.id, v.author_id::uuid, v.body, v.created_at
  from (values
    ('music', 12, '22222222-2222-4222-8222-222222222222',
     'warped ones still play, they just wobble. it grows on you.', now() - interval '70 minutes'),
    ('music', 12, '33333333-3333-4333-8333-333333333333',
     'what was in there', now() - interval '44 minutes'),
    ('poker', 1, '11111111-1111-4111-8111-111111111111',
     'the tip is the tell', now() - interval '2 hours'),
    ('latenight', 1, '22222222-2222-4222-8222-222222222222',
     'the refrigerator and i are also here', now() - interval '7 hours'),
    ('kitchen', 1, '44444444-4444-4444-8444-444444444444',
     'freeze it flat in bags, it stacks and it thaws in about a minute', now() - interval '4 hours'),
    ('builders', 1, '11111111-1111-4111-8111-111111111111',
     'level is a rumor. matchbook under the short leg and never speak of it again.',
     now() - interval '4 hours'),
    ('builders', 2, '22222222-2222-4222-8222-222222222222',
     'there is always one bolt. it is a law of bicycles.', now() - interval '2 hours'),
    ('crypto', 2, '44444444-4444-4444-8444-444444444444',
     'the not-looking is the strategy. everyone finds this out eventually', now() - interval '60 minutes'),
    ('movies', 2, '33333333-3333-4333-8333-333333333333',
     'that is not about the film', now() - interval '100 minutes'),
    ('feedback', 2, '22222222-2222-4222-8222-222222222222',
     'same. the number being an address is the bit nobody says out loud', now() - interval '40 minutes'),
    -- Somebody else answering on her wall, which is the half of the feature
    -- that is easy to miss: only marisol starts things there, anybody replies.
    ('~marisol', 2, '33333333-3333-4333-8333-333333333333',
     'the fan people are the good people. remember them in winter.',
     now() - interval '9 minutes')
  ) as v (room_slug, post_no, author_id, body, created_at)
  join public.posts p
    on p.room_slug = v.room_slug::citext
   and p.post_no = v.post_no
 where not exists (
   select 1 from public.replies existing
    where existing.post_id = p.id
      and existing.body = v.body
 );

-- §3.4 — leave the allocator above every number the seed used, so the first
-- real post continues the sequence instead of colliding with it.
update public.rooms r
   set next_post_no = coalesce(
     (select max(p.post_no) + 1 from public.posts p where p.room_slug = r.slug),
     1
   );

-- The same, one level down: a post's reply allocator above every reply number
-- the seed used, or the first real answer collides with a seeded one.
update public.posts p
   set next_reply_no = coalesce(
     (select max(r.reply_no) + 1 from public.replies r where r.post_id = p.id),
     1
   );

-- The bookkeeping table db-deploy.sh keeps, created here so this project is
-- indistinguishable from one deployed that way. Without it the first
-- db-deploy.sh run against this project falls back to adopting it by probing —
-- which works, but only because all eighteen probes happen to be right, and a
-- wrong one re-runs a migration against a schema that already has it.
create table if not exists public.applied_migrations (
  filename   text primary key,
  applied_at timestamptz not null default now()
);
revoke all on public.applied_migrations from public, anon, authenticated;

